-- ----------------------------
-- Table structure for iast_agent
-- ----------------------------
DROP TABLE IF EXISTS `iast_agent`;
CREATE TABLE `iast_agent` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `token` varchar(255) DEFAULT NULL COMMENT 'agent唯一标识',
  `version` varchar(255) DEFAULT NULL COMMENT '版本',
  `latest_time` int(11) DEFAULT NULL COMMENT '更新时间',
  `user_id` int(11) NOT NULL COMMENT '用户ID',
  `server_id` int(11) DEFAULT NULL COMMENT '服务器ID',
  `is_running` int(1) DEFAULT NULL COMMENT 'agent运行状态',
  `control` int(1) DEFAULT NULL COMMENT 'agent控制位，1-启动、2-暂停、3-审核通过、0-无控制',
  `is_control` int(1) DEFAULT NULL COMMENT '是否正处于控制中，0-否，1-是',
  `bind_project_id` int(11) DEFAULT '0' COMMENT '捆绑项目ID，存在则为已捆绑',
  `project_name` varchar(255) DEFAULT NULL COMMENT '项目名称，用于先启动agent后创建项目',
  `project_version_id` int(11) DEFAULT '0' COMMENT '项目版本ID',
  `online` tinyint(4) DEFAULT '0' COMMENT '1在线运行，0未运行，同token，仅一个online',
  `is_core_running` int(11) DEFAULT NULL COMMENT '核心引擎是否启动',
  `language` varchar(10) DEFAULT 'JAVA' COMMENT '语言，JAVA、PYTHON',
  `alias` varchar(255) NOT NULL DEFAULT '' COMMENT 'agent别名',
  `startup_time` int(11) NOT NULL DEFAULT '0' COMMENT '启动时间',
  `register_time` int(11) NOT NULL DEFAULT '0' COMMENT '注册时间',
  `is_audit` int(11) DEFAULT '1' COMMENT '是否审核',
  `filepathsimhash` varchar(255) NOT NULL DEFAULT '' COMMENT 'agent目录结构相似度哈希',
  `servicetype` varchar(255) NOT NULL DEFAULT '' COMMENT '部署的方式',
  `actual_running_status` int(11) NOT NULL DEFAULT '1' COMMENT '实际运行状态',
  `except_running_status` int(11) NOT NULL DEFAULT '1' COMMENT '期望运行状态',
  `state_status` int(11) NOT NULL DEFAULT '1' COMMENT 'Agent位置状态的原因',
  `events` json DEFAULT NULL COMMENT 'events',
  `department_id` int(11) DEFAULT NULL COMMENT '部门id',
  `allow_report` int(11) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `user_id` (`user_id`) USING BTREE,
  KEY `server_id` (`server_id`) USING BTREE,
  KEY `iast_agent_bind_project_id_IDX` (`bind_project_id`,`project_version_id`) USING BTREE,
  KEY `iast_agent_bind_project_id_single_IDX` (`bind_project_id`) USING BTREE,
  KEY `iast_agent_id_IDX` (`id`,`bind_project_id`) USING BTREE,
  KEY `bind_project_id_language_IDX` (`bind_project_id`,`language`) USING BTREE,
  KEY `language_IDX` (`language`) USING BTREE,
  KEY `iast_agent_user_id_IDX` (`user_id`,`bind_project_id`) USING BTREE,
  KEY `iast_agent_bind_project_id2_IDX` (`bind_project_id`,`user_id`) USING BTREE,
  KEY `iast_agent_filepathsimhash_IDX` (`filepathsimhash`,`language`) USING BTREE,
  KEY `iast_agent_language_IDX` (`language`,`server_id`) USING BTREE,
  KEY `iast_agent_bind_project_id_IDX4` (`bind_project_id`,`department_id`,`server_id`,`latest_time`) USING BTREE
