-- ----------------------------
-- Table structure for iast_asset
-- ----------------------------
DROP TABLE IF EXISTS `iast_asset`;
CREATE TABLE `iast_asset` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `package_name` varchar(255) DEFAULT NULL COMMENT '第三方包名',
