  `project_version_id` int(11) NOT NULL DEFAULT '0' COMMENT '项目版本id',
  `user_id` int(11) DEFAULT '0' COMMENT '用户ID',
  `license` varchar(255) NOT NULL DEFAULT '' COMMENT '许可证',
  `language` varchar(255) NOT NULL DEFAULT '' COMMENT '语言',
  `dependency_level` int(255) NOT NULL DEFAULT '0' COMMENT '依赖层级',
  `parent_dependency_id` int(255) NOT NULL DEFAULT '0' COMMENT '顶级依赖层级',
