  `vul_low_count` int(11) NOT NULL DEFAULT '0' COMMENT '低危漏洞数量',
  `vul_info_count` int(11) NOT NULL DEFAULT '0' COMMENT '无风险漏洞数',
  `project_count` int(11) NOT NULL DEFAULT '0' COMMENT '项目数量',
