  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `signature_value` (`signature_value`) USING BTREE,
  KEY `level_id` (`level_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

