-- ----------------------------
-- Table structure for iast_asset_vul
-- ----------------------------
DROP TABLE IF EXISTS `iast_asset_vul`;
CREATE TABLE `iast_asset_vul` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `vul_name` varchar(255) DEFAULT NULL COMMENT '关联 iast_aql_info',
  `search_title` varchar(1000) DEFAULT NULL COMMENT '为搜索引擎准备的标题',
  `vul_detail` text COMMENT '漏洞详情',
  `level_id` tinyint(2) DEFAULT NULL COMMENT '漏洞等级',
  `license` varchar(50) DEFAULT NULL COMMENT '漏洞标题+编号(fulltext)',
  `license_level` tinyint(2) DEFAULT NULL COMMENT '可利用性',
  `aql` varchar(255) DEFAULT NULL COMMENT 'aql 标识',
  `package_name` varchar(255) DEFAULT NULL,
  `package_hash` varchar(255) DEFAULT NULL COMMENT '组件hash',
  `package_version` varchar(255) DEFAULT NULL COMMENT '组件版本',
  `package_fix_version` varchar(255) DEFAULT NULL COMMENT '当前漏洞修复版本',
  `package_safe_version` varchar(255) DEFAULT NULL COMMENT '组件安全版本',
  `package_latest_version` varchar(255) DEFAULT NULL COMMENT '组件最新版本',
  `package_language` varchar(10) DEFAULT NULL COMMENT '组件语言 JAVA\\GO',
  `vul_cve_nums` json DEFAULT NULL COMMENT 'cve 编号 详情',
  `vul_serial` varchar(255) DEFAULT NULL COMMENT '# 漏洞编号  CWE|CVE等数据',
  `have_article` tinyint(2) DEFAULT '0' COMMENT '1存在分析文章 0 不存在\r\n',
  `have_poc` tinyint(2) DEFAULT '0' COMMENT '1存在可利用poc 0不存在',
  `cve_code` varchar(64) DEFAULT NULL COMMENT '漏洞CVE编号',
  `cve_id` int(11) DEFAULT '0' COMMENT '漏洞编号关联id',
  `vul_publish_time` datetime DEFAULT NULL COMMENT '漏洞发现时间',
  `vul_update_time` datetime DEFAULT NULL COMMENT '漏洞更新时间',
  `update_time` int(11) DEFAULT NULL COMMENT '更新时间',
  `create_time` int(11) DEFAULT NULL COMMENT '创建时间',
  `update_time_desc` int(11) DEFAULT NULL COMMENT '-更新时间 倒序',
  `sid` varchar(64) DEFAULT '' COMMENT '漏洞唯一编号',
  `poc` json DEFAULT NULL COMMENT 'poc',
  `fix_plan` json DEFAULT NULL COMMENT 'fix_plan',
  `descriptions` json DEFAULT NULL COMMENT 'descriptions',
  `references` json DEFAULT NULL COMMENT 'references',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `iast_asset_vul_UN` (`sid`),
  KEY `idx_cve_code` (`cve_code`) USING BTREE,
  KEY `idx_pkg_hash` (`package_hash`) USING BTREE,
  KEY `create_time_order` (`create_time`) USING BTREE,
  KEY `update_time_order` (`update_time`) USING BTREE,
  KEY `have_poc_index` (`have_poc`) USING BTREE,
  KEY `have_article_index` (`have_article`) USING BTREE,
  KEY `level_update_order_asc` (`level_id`,`update_time_desc`) USING BTREE,
  KEY `package_language_where` (`package_language`) USING BTREE,
  KEY `level_update_order_desc` (`level_id`,`update_time`) USING BTREE,
  FULLTEXT KEY `ft_index_search` (`vul_name`,`aql`,`vul_serial`),
  FULLTEXT KEY `search_index` (`license`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

