-- ----------------------------
-- Table structure for iast_hook_strategy
-- ----------------------------
DROP TABLE IF EXISTS `iast_hook_strategy`;
CREATE TABLE `iast_hook_strategy` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `value` varchar(2000) DEFAULT NULL COMMENT '策略值',
  `source` varchar(255) DEFAULT NULL COMMENT '污点来源',
  `target` varchar(255) DEFAULT NULL COMMENT '污点去向',
  `inherit` varchar(255) DEFAULT NULL COMMENT '继承类型，false-仅检测当前类，true-进检测子类，all-检测当前类及子类',
  `track` varchar(5) DEFAULT NULL COMMENT '是否需要污点跟踪，true-需要，false-不需要',
  `create_time` int(11) DEFAULT NULL COMMENT '创建时间',
  `update_time` int(11) DEFAULT NULL COMMENT '修改时间',
  `created_by` int(11) DEFAULT NULL COMMENT '创建人',
  `enable` tinyint(1) DEFAULT '1' COMMENT '启用状态：0-禁用，1-启用，-1-删除',
  `hooktype_id` int(11) DEFAULT '0' COMMENT '策略类型ID',
  `strategy_id` int(11) NOT NULL DEFAULT '0',
  `type` int(11) NOT NULL DEFAULT '0' COMMENT '策略总类型，1-source节点、2-propagator节点、3-filter节点、4-sink节点',
  `language_id` int(11) NOT NULL DEFAULT '0',
  `system_type` int(11) NOT NULL DEFAULT '0',
  `ignore_blacklist` int(11) NOT NULL DEFAULT '0',
  `ignore_internal` int(11) NOT NULL DEFAULT '0',
  `command` varchar(255) NOT NULL DEFAULT '' COMMENT '污点范围',
  `tags` json DEFAULT NULL COMMENT '污点标记',
  `untags` json DEFAULT NULL COMMENT '污点反标记',
  `stack_blacklist` json DEFAULT NULL COMMENT '调用栈黑名单',
  `modified` tinyint(1) NOT NULL,
  `pref_level` int(11) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `iast_hook_strategy_enable_IDX` (`enable`,`language_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=44352 DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of iast_hook_strategy
-- ----------------------------
BEGIN;
COMMIT;

