-- ----------------------------
-- Table structure for iast_replay_queue
-- ----------------------------
DROP TABLE IF EXISTS `iast_replay_queue`;
CREATE TABLE `iast_replay_queue` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `relation_id` int(11) DEFAULT NULL COMMENT '待检测的漏洞ID',
  `state` int(1) DEFAULT NULL COMMENT '状态，0-待处理、1-待重放、2-已重放',
  `count` int(11) DEFAULT NULL COMMENT '重放次数',
  `result` int(1) DEFAULT NULL COMMENT '重放结果，0-无漏洞，1-存在漏洞，2-失败',
  `create_time` int(11) DEFAULT NULL COMMENT '创建时间',
  `update_time` int(11) DEFAULT NULL COMMENT '更新时间',
  `verify_time` int(11) DEFAULT NULL COMMENT '结果更新时间',
  `uri` varchar(2000) DEFAULT NULL COMMENT '目标URI',
  `method` varchar(10) DEFAULT NULL COMMENT '请求方法',
  `scheme` varchar(10) DEFAULT NULL COMMENT '请求协议，http/https',
  `header` varchar(4000) DEFAULT NULL COMMENT '请求头',
  `params` varchar(2000) DEFAULT NULL COMMENT '参数',
  `body` varchar(4000) DEFAULT NULL COMMENT '请求体',
  `replay_type` int(1) DEFAULT NULL COMMENT '重放类型，1-漏洞重放、2-请求重放',
  `agent_id` int(11) DEFAULT NULL COMMENT 'Agent ID，外键',
  `payload_id` int(11) NOT NULL DEFAULT '-1' COMMENT 'Payload ID，外键',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `iast_replay_queue_agent_id_IDX` (`agent_id`,`state`,`replay_type`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of iast_replay_queue
-- ----------------------------
BEGIN;
COMMIT;

