  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `project_id` int(11) DEFAULT NULL COMMENT '项目ID',
  `agent_id` int(11) DEFAULT NULL COMMENT '来源agentID',
  `port` varchar(255) DEFAULT NULL COMMENT '端口',
  `address` varchar(255) DEFAULT NULL COMMENT '地址',
  `service_type` varchar(255) DEFAULT NULL COMMENT '服务类型',
  PRIMARY KEY (`id`),
  UNIQUE KEY `iast_third_party_service_UN` (`address`,`service_type`,`port`,`agent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of iast_third_party_service
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for iast_vul_all
-- ----------------------------
DROP TABLE IF EXISTS `iast_vul_all`;
CREATE TABLE `iast_vul_all` (
  `id` int(11) unsigned zerofill NOT NULL AUTO_INCREMENT,
  `vul_title` varchar(255) DEFAULT NULL COMMENT '漏洞标题',
  `vul_number` varchar(255) DEFAULT NULL COMMENT '漏洞编号',
  `vul_type_name` varchar(255) DEFAULT NULL COMMENT '漏洞类型名称',
  `availability` tinyint(2) DEFAULT NULL COMMENT '可利用性',
  `language` tinyint(2) DEFAULT NULL COMMENT '探针语言',
  `level_id` tinyint(2) DEFAULT NULL COMMENT '漏洞等级',
  `user_id` int(11) DEFAULT NULL COMMENT '用户id',
  `department_id` int(5) DEFAULT '0' COMMENT '部门id',
  `talent_id` int(5) DEFAULT '0' COMMENT '租户id',
  `first_time` int(11) DEFAULT NULL COMMENT '第一次发现时间',
  `last_time` int(11) DEFAULT NULL COMMENT '上一次发现时间',
  `aggregation` varchar(255) DEFAULT NULL COMMENT '聚合条件',
  `source_type` tinyint(2) DEFAULT '1' COMMENT '漏洞来源 1 应用漏洞 2组件漏洞',
  `source_vul_id` int(11) DEFAULT NULL COMMENT '应用漏洞id/组件漏洞aql_id',
  `is_del` tinyint(2) DEFAULT '0' COMMENT '默认0有效，1已删除',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `level_index` (`level_id`) USING BTREE,
  KEY `lang_index` (`language`) USING BTREE,
  KEY `group_index` (`aggregation`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

-- ----------------------------
-- Records of iast_vul_all
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for iast_vul_integration
