  `msg` text COMMENT '日志详情',
  `meta_data` json DEFAULT NULL COMMENT '日志原始数据',
  `datetime` int(11) DEFAULT NULL COMMENT '日志触发时间',
  `user_id` int(11) DEFAULT NULL COMMENT 'user id',
  `asset_vul_id` int(11) DEFAULT NULL COMMENT 'agent id',
  `vul_id` int(11) DEFAULT NULL COMMENT 'vul id',
  `msg_type` int(11) DEFAULT NULL COMMENT '日志类型',
  PRIMARY KEY (`id`) USING BTREE
