BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for iast_vulnerability
-- ----------------------------
DROP TABLE IF EXISTS `iast_vulnerability`;
CREATE TABLE `iast_vulnerability` (
  `id` int(11) NOT NULL AUTO_INCREMENT COMMENT '自增主键',
  `level_id` int(11) DEFAULT NULL COMMENT '漏洞等级',
  `level_id_desc` int(11) NOT NULL DEFAULT '-1' COMMENT '-1 * level，解决mysql7 mix order无法使用索引的问题',
  `url` varchar(2000) DEFAULT NULL COMMENT '漏洞url',
  `uri` varchar(255) DEFAULT '' COMMENT 'uri',
  `http_method` varchar(10) DEFAULT NULL COMMENT '漏洞请求方法',
  `http_scheme` varchar(255) DEFAULT NULL COMMENT '协议名',
  `http_protocol` varchar(255) DEFAULT NULL COMMENT 'HTTP协议',
  `req_header` mediumtext COMMENT '漏洞请求的header头',
  `req_params` varchar(2000) DEFAULT NULL COMMENT '漏洞url的get参数',
  `req_data` mediumtext COMMENT '漏洞url的post数据信息',
  `res_header` mediumtext COMMENT '漏洞响应头',
  `res_body` mediumtext COMMENT '漏洞响应包',
  `full_stack` longtext NOT NULL,
  `top_stack` varchar(255) NOT NULL,
  `bottom_stack` varchar(255) NOT NULL,
  `taint_value` varchar(4000) NOT NULL,
  `taint_position` varchar(255) NOT NULL,
  `agent_id` int(11) DEFAULT '0' COMMENT '应用ID',
  `context_path` varchar(255) DEFAULT NULL COMMENT '漏洞所在应用',
  `counts` int(11) DEFAULT NULL COMMENT '漏洞出现次数',
  `status` varchar(255) DEFAULT NULL COMMENT '漏洞状态：已上报、已确认、已忽略',
  `first_time` int(11) DEFAULT NULL COMMENT '漏洞第一次出现的时间',
  `latest_time` int(11) DEFAULT NULL COMMENT '漏洞最近一次出现的时间',
  `latest_time_desc` int(11) NOT NULL DEFAULT '0' COMMENT '-1*latest_time,为了解决mysql7中 mix order无法使用索引的问题',
  `client_ip` varchar(255) DEFAULT NULL COMMENT '来源IP',
  `param_name` varchar(255) NOT NULL,
  `method_pool_id` int(11) DEFAULT '0' COMMENT '方法池ID ',
  `hook_type_id` int(11) NOT NULL DEFAULT '0' COMMENT '漏洞类型id',
  `status_id` int(11) NOT NULL DEFAULT '0' COMMENT '漏洞状态id',
  `strategy_id` int(11) NOT NULL DEFAULT '0' COMMENT '漏洞类型-策略id',
  `is_del` tinyint(2) DEFAULT '0' COMMENT '0有效1删除',
  `search_keywords` varchar(1000) DEFAULT NULL,
  `vul_title` varchar(255) DEFAULT NULL COMMENT '组合后的漏洞标题',
  `pattern_uri` varchar(255) NOT NULL,
  `project_id` int(11) DEFAULT '0' COMMENT '项目ID',
  `project_version_id` int(11) DEFAULT '0' COMMENT '应用ID',
  `server_id` int(11) DEFAULT '0' COMMENT 'server',
  `language` varchar(10) NOT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  KEY `agent_id` (`agent_id`) USING BTREE,
  KEY `level_id` (`level_id`) USING BTREE,
  KEY `iast_vulnerability_uri_IDX` (`uri`,`agent_id`) USING BTREE,
  KEY `iast_vulnerability_level_id_IDX` (`level_id`,`agent_id`) USING BTREE,
  KEY `iast_vulnerability_method_pool_id_IDX` (`method_pool_id`,`hook_type_id`,`strategy_id`) USING BTREE,
  KEY `status_id_strategy_id_agent_id` (`status_id`,`strategy_id`,`agent_id`) USING BTREE,
  KEY `iast_vulnerability_strategy_id_IDX` (`strategy_id`,`hook_type_id`,`http_method`,`uri`,`method_pool_id`) USING BTREE,
  KEY `strategy_id_IDX` (`strategy_id`) USING BTREE,
  KEY `strategy_id_is_del_IDX` (`strategy_id`,`is_del`) USING BTREE,
  KEY `level_id_is_del` (`level_id`,`is_del`) USING BTREE,
  KEY `is_del_agent_id` (`is_del`,`agent_id`) USING BTREE,
  KEY `is_del_level_id_latest_time` (`level_id`,`latest_time`,`is_del`) USING BTREE,
  KEY `level_id_latest_time_desc_order` (`level_id`,`latest_time_desc`) USING BTREE,
  KEY `level_id_latest_time_order` (`level_id`,`latest_time`) USING BTREE,
  KEY `first_time_order` (`first_time`) USING BTREE,
  KEY `latest_time_order` (`latest_time`) USING BTREE,
  KEY `status_order` (`status`) USING BTREE,
  KEY `iast_vulnerability_agent_id_IDX` (`agent_id`,`level_id`) USING BTREE,
  KEY `iast_vulnerability_agent_id_strategy_IDX` (`agent_id`,`strategy_id`,`level_id`) USING BTREE,
  KEY `iast_vulnerability_distinct_IDX` (`uri`,`http_method`,`agent_id`,`param_name`,`strategy_id`) USING BTREE,
  KEY `iast_vulnerability_project_id_IDX` (`project_id`,`project_version_id`,`server_id`,`is_del`,`level_id`,`latest_time_desc`) USING BTREE,
  KEY `iast_vulnerability_is_del_IDX` (`is_del`,`project_id`,`project_version_id`) USING BTREE,
  KEY `iast_vulnerability_uri_IDX2` (`uri`,`project_id`,`project_version_id`,`server_id`,`is_del`,`level_id`,`latest_time_desc`) USING BTREE,
  KEY `iast_vulner_http_me_f84d4f_idx` (`http_method`,`param_name`,`pattern_uri`,`project_id`,`status_id`,`strategy_id`),
  FULLTEXT KEY `ft_index_http_method` (`http_method`),
  FULLTEXT KEY `ft_index_http_protocol` (`http_protocol`),
  FULLTEXT KEY `ft_index_top_stack` (`top_stack`),
  FULLTEXT KEY `ft_index_bottom_stack` (`bottom_stack`),
  FULLTEXT KEY `ft_index_uri` (`uri`),
  FULLTEXT KEY `ft_index_search_keywords` (`search_keywords`),
  FULLTEXT KEY `ft_index_vul_title` (`vul_title`),
  FULLTEXT KEY `ft_index_search` (`search_keywords`,`uri`,`vul_title`,`http_method`,`http_protocol`,`top_stack`,`bottom_stack`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ----------------------------
-- Records of iast_vulnerability
-- ----------------------------
BEGIN;
COMMIT;

